{"command": "cat > /tmp/metrics.py <<'EOF'
def jaro(s1,s2):
    if s1==s2: return 1.0
    l1,l2=len(s1),len(s2)
    if l1==0 or l2==0: return 0.0
    md=max(l1,l2)//2-1
    if md<0: md=0
    f1=[False]*l1; f2=[False]*l2; m=0
    for i in range(l1):
        lo=max(0,i-md); hi=min(l2,i+md+1)
        for j in range(lo,hi):
            if not f2[j] and s1[i]==s2[j]:
                f1[i]=f2[j]=True; m+=1; break
    if m==0: return 0.0
    t=0; k=0
    for i in range(l1):
        if f1[i]:
            while not f2[k]: k+=1
            if s1[i]!=s2[k]: t+=1
            k+=1
    t//=2
    return (m/l1+m/l2+(m-t)/m)/3
def jw4(s1,s2):
    j=jaro(s1,s2)
    p=0
    while p<4 and p<len(s1) and p<len(s2) and s1[p]==s2[p]: p+=1
    j+= 0.1*p*(1-j)
    return min(j,1.0)
def jwU(s1,s2):
    j=jaro(s1,s2)
    p=0
    while p<len(s1) and p<len(s2) and s1[p]==s2[p]: p+=1
    j+= 0.1*p*(1-j)
    return min(j,1.0)
def lev(a,b):
    if len(a)<len(b): a,b=b,a
    prev=list(range(len(b)+1))
    for i,ca in enumerate(a,1):
        cur=[i]
        for j,cb in enumerate(b,1):
            cur.append(min(prev[j]+1,cur[j-1]+1,prev[j-1]+(ca!=cb)))
        prev=cur
    return prev[-1]
def nlev(a,b): return 1-lev(a,b)/max(len(a),len(b))
cands="show-all nonprintable-notation binary plain language fallback-syntax highlight-line file-name diff diff-context tabs wrap chop-long-lines terminal-width number color italic-text decorations force-colorization paging no-paging pager map-syntax ignored-suffix theme theme-light theme-dark list-themes squeeze-blank squeeze-limit strip-ansi style line-range list-languages unbuffered completion set-terminal-title diagnostic quiet-empty acknowledgements no-config no-custom-assets lessopen no-lessopen config-dir cache-dir config-file generate-config-file help version".split()
tests={'badoption':'decorations','themes':'theme','linenumbers':'number','line-numbers':'line-range','numb':'number','zzz':None,'line':'line-range','pagerr':'pager','pagr':'pager','themee':'theme','styless':'style','formatchanges':None,'colour':'color','list-language':'list-languages','config':'config-dir','cache':'cache-dir','xyz':None}
for name,f in [('jw4',jw4),('jwU',jwU),('nlev',nlev),('jaro',jaro)]:
    ok=0
    for t,exp in tests.items():
        scored=sorted(((f(t,c),c) for c in cands), reverse=True)
        top=[s for s in scored if s[0]>0.7][:3]
        got=top[0][1] if top else None
        if got==exp: ok+=1
        else: print("  %s %s exp=%s got=%s %s"%(name,t,exp,got,scored[:2]))
    print(name,"score",ok,"/",len(tests))
EOF
python3 /tmp/metrics.py"}

