{"command": "cd /workspace; cat > src/config.rs <<'EOF'
use crate::args::{ArgDef, Val};

#[derive(Clone, Copy, PartialEq)]
pub enum Tri { Auto, Never, Always }

#[derive(Clone, Copy, PartialEq)]
pub enum WrapMode { Auto, Never, Character, Word }

#[derive(Clone, Copy, PartialEq)]
pub enum BinaryMode { NoPrinting, AsText }

#[derive(Clone, Copy, PartialEq)]
pub enum Notation { Unicode, Caret }

#[derive(Clone)]
pub struct LineRange {
    pub start: Option<usize>, // 1-based
    pub end: Option<usize>,
    pub ctx: usize,
}

#[derive(Clone, PartialEq, Copy)]
pub enum StyleComp { Changes, HeaderFilename, HeaderFilesize, Grid, Rule, Numbers, Snip }

pub struct Config {
    pub files: Vec<String>,
    pub language: Option<String>,
    pub fallback_syntax: Option<String>,
    pub show_all: bool,
    pub notation: Notation,
    pub binary: BinaryMode,
