    pub ignored_suffixes: Vec<String>,
    pub theme: Option<String>,
    pub list_themes: bool,
    pub squeeze_blank: bool,
    pub squeeze_limit: usize,
    pub strip_ansi: Tri,
    pub style: Vec<StyleComp>,
