pub struct CfgErr(pub String);

pub fn possible(v: &[&str]) -> String { v.join(", ") }

fn err_val(d: &ArgDef, v: &str, vals: &[&str]) -> CfgErr {
    CfgErr(format!("error: invalid value '{}' for '{}'\n  [possible values: {}]\n", v, d.usage, possible(vals)))
}

pub fn parse_style(v: &str) -> Result<Vec<StyleComp>, String> {
    let comps: Vec<&str> = v.split(',').collect();
    let mut out: Vec<StyleComp> = Vec::new();
    let only_delta = !comps.is_empty() && comps.iter().all(|c| c.starts_with('+') || c.starts_with('-'));
    let _ = only_delta;
    for comp in comps {
        match comp {
            "default" => { out = DEFAULT_STYLE.to_vec(); }
            "full" => { out = vec![StyleComp::Changes, StyleComp::HeaderFilename, StyleComp::HeaderFilesize, StyleComp::Grid, StyleComp::Numbers, StyleComp::Snip]; }
