    Ok(out)
}

pub fn apply(cfg: &mut Config, d: &ArgDef, v: &str, first: bool) -> Result<(), CfgErr> {
    match d.long {
        "show-all" => cfg.show_all = true,
        "nonprintable-notation" => {
            cfg.notation = match v {
                "unicode" => Notation::Unicode,
                "caret" => Notation::Caret,
                _ => return Err(err_val(d, v, &["unicode", "caret"])),
            };
        }
        "binary" => {
            cfg.binary = match v {
                "no-printing" => BinaryMode::NoPrinting,
                "as-text" => BinaryMode::AsText,
                _ => return Err(err_val(d, v, &["no-printing", "as-text"])),
            };
        }
        "plain" => cfg.plain_count += 1,
        "language" => { cfg.language = Some(v.to_string()); }
        "fallback-syntax" => { cfg.fallback_syntax = Some(v.to_string()); }
        "highlight-line" => match parse_range(v) {
            Some(r) => cfg.highlight_lines.push(r),
            None => return Err(CfgErr("[bat error]: invalid digit found in string\n".into())),
        },
        "file-name" => cfg.file_name = Some(v.to_string()),
        "diff" => cfg.diff = true,
        "diff-context" => match v.parse::<usize>() {
            Ok(n) => cfg.diff_context = n,
            Err(_) => return Err(CfgErr("[bat error]: invalid digit found in string\n".into())),
        },
        "tabs" => match v.parse::<usize>() {
            Ok(n) => cfg.tabs = n,
            Err(_) => return Err(crate::parser::invalid_value_msg(v, d, "must be a number").msg.into()),
        },
        "wrap" => {
            cfg.wrap = match v {
                "auto" => WrapMode::Auto,
                "never" => WrapMode::Never,
                "character" => WrapMode::Character,
                "word" => WrapMode::Word,
                _ => return Err(err_val(d, v, &["auto", "never", "character", "word"])),
            };
        }
        "chop-long-lines" => cfg.wrap = WrapMode::Never,
        "terminal-width" => {
            if v.is_empty() { return Err(crate::parser::invalid_value_msg(v, d, "must be an offset or number").msg.into()); }
            if let Some(rest) = v.strip_prefix('+') {
                let n: i64 = match rest.parse() { Ok(n) => n, Err(_) => return Err(crate::parser::invalid_value_msg(v, d, "must be an offset or number").msg.into()) };
                let base = crate::sys::term_width_fallback() as i64;
                let t = base + n;
                cfg.terminal_width = Some(if t < 0 { 0 } else { t as usize });
            } else if let Some(rest) = v.strip_prefix('-') {
                let n: i64 = match rest.parse() { Ok(n) => n, Err(_) => return Err(crate::parser::invalid_value_msg(v, d, "must be an offset or number").msg.into()) };
                let base = crate::sys::term_width_fallback() as i64;
                let t = base - n;
                cfg.terminal_width = Some(if t < 0 { 0 } else { t as usize });
            } else {
                match v.parse::<usize>() {
                    Ok(n) => cfg.terminal_width = Some(n),
                    Err(_) => return Err(crate::parser::invalid_value_msg(v, d, "must be an offset or number").msg.into()),
                }
            }
        }
        "number" => cfg.number = true,
        "color" => cfg.color = parse_tri(d, v, &["auto", "never", "always"])?,
        "italic-text" => cfg.italic_text = parse_tri(d, v, &["always", "never"])?,
        "decorations" => cfg.decorations = parse_tri(d, v, &["auto", "never", "always"])?,
        "force-colorization" => { cfg.decorations = Tri::Always; cfg.color = Tri::Always; }
        "paging" => cfg.paging = parse_tri(d, v, &["auto", "never", "always"])?,
        "no-paging" => cfg.paging = Tri::Never,
        "pager" => cfg.pager = Some(v.to_string()),
        "map-syntax" => {
            match v.find(':') {
                Some(p) => cfg.map_syntax.push((v[..p].to_string(), v[p + 1..].to_string())),
                None => return Err(CfgErr("[bat error]: Invalid syntax mapping. The format of the -m/--map-syntax option is '<glob-pattern>:<syntax-name>'. For example: '*.cpp:C++'.\n".into())),
            }
        }
        "ignored-suffix" => cfg.ignored_suffixes.push(v.to_string()),
        "theme" => cfg.theme = Some(v.to_string()),
        "theme-light" => cfg.theme = Some(v.to_string()),
        "theme-dark" => cfg.theme = Some(v.to_string()),
        "list-themes" => cfg.list_themes = true,
        "squeeze-blank" => cfg.squeeze_blank = true,
        "squeeze-limit" => match v.parse::<usize>() {
            Ok(n) => cfg.squeeze_limit = n,
            Err(_) => return Err(crate::parser::invalid_value_msg(v, d, "Requires a non-negative number").msg.into()),
        },
        "strip-ansi" => cfg.strip_ansi = parse_tri(d, v, &["auto", "always", "never"])?,
        "style" => match parse_style(v) {
            Ok(s) => cfg.style = s,
            Err(msg) => return Err(crate::parser::invalid_value_msg(v, d, &msg).msg.into()),
        },
        "line-range" => match parse_range(v) {
            Some(r) => cfg.line_ranges.push(r),
            None => return Err(CfgErr("[bat error]: invalid digit found in string\n".into())),
        },
        "list-languages" => cfg.list_languages = true,
        "unbuffered" => cfg.unbuffered = true,
        "completion" => {
            cfg.completion = Some(match v {
                "bash" | "fish" | "zsh" | "ps1" => v.to_string(),
                _ => {
                    let mut vals = vec!["bash", "fish", "ps1", "zsh"];
                    vals.sort();
                    return Err(err_val(d, v, &vals));
                }
            });
        }
        "set-terminal-title" => cfg.set_terminal_title = true,
        "diagnostic" => cfg.diagnostic = true,
        "quiet-empty" => cfg.quiet_empty = true,
        "acknowledgements" => cfg.acknowledgements = true,
        "no-config" => cfg.no_config = true,
        "no-custom-assets" => cfg.no_custom_assets = true,
        "config-dir" => cfg.config_dir = true,
        "cache-dir" => cfg.cache_dir = true,
        "config-file" => cfg.config_file = true,
        "generate-config-file" => cfg.generate_config_file = true,
        "help" => cfg.help = true,
        "version" => cfg.version = true,
        _ => {}
    }
    Ok(())
}

fn parse_tri(d: &ArgDef, v: &str, vals: &[&str]) -> Result<Tri, CfgErr> {
    match v {
        "auto" => Ok(Tri::Auto),
        "never" => Ok(Tri::Never),
        "always" => Ok(Tri::Always),
        _ => Err(err_val(d, v, vals)),
    }
}

/// Parse 'N:M', 'N', ':M', 'N:', '-N:', 'N:+M', 'N::ctx', 'N:M:ctx'
pub fn parse_range(s: &str) -> Option<LineRange> {
    if s.is_empty() { return None; }
    let parts: Vec<&str> = s.split(':').collect();
    let (start_s, end_s, ctx) = match parts.len() {
        1 => (Some(parts[0]), None, 0),
        2 => (if parts[0].is_empty() { None } else { Some(parts[0]) },
              if parts[1].is_empty() { None } else { Some(parts[1]) }, 0),
        3 => (if parts[0].is_empty() { None } else { Some(parts[0]) },
              if parts[1].is_empty() { None } else { Some(parts[1]) },
              if parts[2].is_empty() { 0 } else { parts[2].parse::<usize>().ok()? }),
        _ => return None,
    };
    let mut start: Option<usize> = None;
    let mut end: Option<usize> = None;
    let mut ctx = ctx;
    match (start_s, end_s) {
        (Some(a), Some(b)) => {
            let a = a.to_string();
            let b = b.to_string();
            if a.starts_with('-') {
                // -N:  => last N lines
                let n: usize = a[1..].parse().ok()?;
                start = Some(n); end = Some(usize::MAX); ctx = usize::MAX - n; // marker
                return Some(LineRange { start: Some(n), end: None, ctx: usize::MAX });
            } else if b.starts_with('+') {
                let a: usize = a.parse().ok()?;
                let n: usize = b[1..].parse().ok()?;
                start = Some(a); end = Some(a + n); ctx = n;
            } else {
                let a: usize = a.parse().ok()?;
                let b: usize = b.parse().ok()?;
                start = Some(a); end = Some(b); ctx = if b >= a { b - a } else { 0 };
            }
        }
        (Some(a), None) => {
            let a = a.to_string();
            if a.starts_with('-') {
                let n: usize = a[1..].parse().ok()?;
                return Some(LineRange { start: Some(n), end: None, ctx: usize::MAX });
            }
            let a: usize = a.parse().ok()?;
            start = Some(a); end = Some(a); ctx = 0;
        }
        (None, Some(b)) => {
            let b = b.to_string();
            if b.starts_with('+') {
                let n: usize = b[1..].parse().ok()?;
                start = Some(1); end = Some(n); ctx = n;
            } else {
                let b: usize = b.parse().ok()?;
                start = Some(1); end = Some(b); ctx = b;
            }
        }
        (None, None) => { start = Some(1); end = None; }
    }
    Some(LineRange { start, end, ctx })
}
