const TIOCGWINSZ: u64 = 0x5413;

#[repr(C)]
#[derive(Default)]
struct Winsize { ws_row: u16, ws_col: u16, ws_xpixel: u16, ws_ypixel: u16 }

pub fn is_tty(fd: i32) -> bool { unsafe { isatty(fd) == 1 } }

pub fn tty_width() -> Option<usize> {
    unsafe {
        let mut ws = Winsize::default();
        if ioctl(1, TIOCGWINSZ, &mut ws as *mut Winsize) == 0 && ws.ws_col > 0 {
            Some(ws.ws_col as usize)
        } else {
            let mut ws2 = Winsize::default();
            if ioctl(0, TIOCGWINSZ, &mut ws2 as *mut Winsize) == 0 && ws2.ws_col > 0 {
                Some(ws2.ws_col as usize)
            } else { None }
        }
    }
}

pub fn term_width_fallback() -> usize { 80 }

pub fn stdout_is_tty() -> bool { is_tty(1) }
