/// textwrap-like wrapping helpers
pub fn char_wrap(s: &str, width: usize) -> Vec<String> {
    if width == 0 { return vec![s.to_string()]; }
    let mut out = Vec::new();
    let mut cur = String::new();
    let mut curw = 0usize;
    for ch in s.chars() {
        let w = char_width(ch);
        if curw + w > width && !cur.is_empty() {
            out.push(std::mem::take(&mut cur));
            curw = 0;
        }
        cur.push(ch);
        curw += w;
    }
    if !cur.is_empty() || out.is_empty() { out.push(cur); }
    out
}

pub fn word_wrap(s: &str, width: usize) -> Vec<String> {
    if width == 0 { return vec![s.to_string()]; }
    // textwrap-compatible word wrapping with hard break of long words
    let mut out: Vec<String> = Vec::new();
    let mut cur = String::new();
    let mut curw = 0usize;
    let mut word = String::new();
    let mut wordw = 0usize;
    let mut flush_word = |out: &mut Vec<String>, cur: &mut String, curw: &mut usize, word: &mut String, wordw: &mut usize| {
        if word.is_empty() { return; }
        let ww = *wordw;
        let sep_needed = !cur.is_empty();
        let sepw = if sep_needed { 1 } else { 0 };
        if *curw + sepw + ww <= width || cur.is_empty() {
            if sep_needed { cur.push(' '); *curw += 1; }
            cur.push_str(word);
            *curw += ww;
        } else {
            out.push(std::mem::take(cur));
            *curw = 0;
            if ww <= width {
                cur.push_str(word);
                *curw = ww;
            } else {
                // hard break
                let mut it = word.chars();
                let mut w = 0;
                let mut first = true;
                loop {
                    let c = match it.next() { Some(c) => c, None => break };
                    let cw = char_width(c);
                    if w + cw > width && w > 0 {
                        out.push(std::mem::take(cur));
                        w = 0;
                        first = false;
                        let _ = first;
                    }
                    cur.push(c);
                    w += cw;
                }
                *curw = w;
            }
        }
        word.clear();
        *wordw = 0;
    };
    for ch in s.chars() {
        if ch == ' ' {
            flush_word(&mut out, &mut cur, &mut curw, &mut word, &mut wordw);
            // pending separator
            if !cur.is_empty() { pending_sep = true; }
        } else {
            word.push(ch);
            wordw += char_width(ch);
        }
    }
    flush_word(&mut out, &mut cur, &mut curw, &mut word, &mut wordw);
    if out.is_empty() { out.push(String::new()); }
    out
}

static mut pending_sep: bool = false;

pub fn char_width(c: char) -> usize {
    let cp = c as u32;
    if cp == 0 { return 0; }
    if cp < 0x20 { return 0; }
    if (0x0300..=0x036F).contains(&cp) { return 0; }
    // CJK and wide ranges
    if (0x1100..=0x115F).contains(&cp) || (0x2E80..=0xA4CF).contains(&cp) && cp != 0x303F
        || (0xAC00..=0xD7A3).contains(&cp) || (0xF900..=0xFAFF).contains(&cp)
        || (0xFE30..=0xFE6F).contains(&cp) || (0xFF00..=0xFF60).contains(&cp)
        || (0xFFE0..=0xFFE6).contains(&cp) || (0x20000..=0x3FFFD).contains(&cp) { return 2; }
    1
}

pub fn display_width(s: &str) -> usize { s.chars().map(char_width).sum() }
