import subprocess,re
themes=[l.strip() for l in open('/workspace/assets/themes.txt') if l.strip()]
def runs(args):
    p=subprocess.run(args,capture_output=True)
    out=p.stdout.decode('utf8','replace')
    parts=re.split(r'(\x1b\[[0-9;]*m)',out)
    segs=[];cur=''
    for p in parts:
        if p.startswith('\x1b['): cur=p[2:-1]
        elif p: segs.append((cur,p))
    return segs
def tc(t):
    # truecolor run colors for the same probe
    p=subprocess.run(['./executable','--color=always','--decorations=never','--theme='+t,'-l','python','/tmp/p.py'],capture_output=True).stdout.decode()
    parts=re.split(r'(\x1b\[[0-9;]*m)',p)
    segs=[];cur=''
    for x in parts:
        if x.startswith('\x1b['): cur=x[2:-1]
        elif x: segs.append((cur,x))
    return segs
print('# frame + plain + python tokens (256 / truecolor)')
for t in themes:
    a=runs(['./executable','--color=always','--decorations=always','--theme='+t,'/tmp/pt.txt'])
    frame=[s for s,x in a if x.startswith('-----')]
    b=tc(t)
    print(t,'|frame',frame[0] if frame else None,'|py',[ (s,x) for s,x in b][:4])
