use crate::config::*;
use crate::wrap::*;
use std::io::Write;

pub struct ThemeColors {
    pub frame: String,   // ANSI prefix for frame/line numbers
    pub fg: String,      // ANSI prefix for plain text
}

pub struct Printer<'a> {
    pub cfg: &'a Config,
    pub style: &'a [StyleComp],
    pub color: bool,
    pub decor: bool,
    pub theme: &'a crate::theme::ThemeColors,
    pub term_width: usize,
    pub wrap: bool,
    pub numw: usize,
    pub mf: usize,          // change-marker field width (2 when markers exist)
    pub has_changes: bool,
    pub frame: String,
    pub text: String,
    pub italic: bool,
}

impl<'a> Printer<'a> {
    pub fn new(cfg: &'a Config, style: &'a [StyleComp], color: bool, decor: bool,
               theme: &'a crate::theme::ThemeColors, term_width: usize) -> Printer<'a> {
        Printer {
            cfg, style, color, decor, theme, term_width,
            wrap: false, numw: 0, mf: 0, has_changes: false,
            frame: theme.frame.clone(), text: theme.fg.clone(),
            italic: false,
        }
    }

    pub fn sidebar(&self) -> usize { self.numw + if self.has_changes { 2 } else { 0 } }
    pub fn content_col(&self) -> usize {
        let mut c = self.numw + if self.numw > 0 { 1 } else { 0 } + if self.has_changes { 2 } else { 0 };
        if crate::config::style_has(self.style, StyleComp::Grid) && self.sidebar() > 0 { c += 2; }
        c
    }
    pub fn content_width(&self) -> usize {
        let c = self.content_col();
        if self.term_width > c { self.term_width - c } else { 0 }
    }

    pub fn esc(&self, code: &str) -> String { if self.color { format!("\x1b[{}m", code) } else { String::new() } }
    pub fn reset(&self) -> String { if self.color { "\x1b[0m".to_string() } else { String::new() } }
    pub fn frame_s(&self, s: &str) -> String { format!("{}{}{}", self.esc(&self.frame), s, self.reset()) }
    pub fn text_s(&self, s: &str) -> String { format!("{}{}{}", self.esc(&self.text), s, self.reset()) }
    pub fn style_s(&self, code: &str, s: &str) -> String { format!("{}{}{}", self.esc(code), s, self.reset()) }

    pub fn horizontal(&self, w: &mut dyn Write) {
        let line: String = std::iter::repeat('─').take(self.term_width).collect();
        let _ = writeln!(w, "{}", self.frame_s(&line));
    }

    pub fn grid_rule(&self, w: &mut dyn Write, mid: char) {
        let sb = self.sidebar();
        if sb == 0 || self.term_width <= sb {
            let line: String = std::iter::repeat('─').take(self.term_width).collect();
            let _ = writeln!(w, "{}", self.frame_s(&line));
        } else {
            let n = self.term_width - sb - 1;
            let mut s = String::new();
            for _ in 0..sb { s.push('─'); }
            s.push(mid);
            for _ in 0..n { s.push('─'); }
            let _ = writeln!(w, "{}", self.frame_s(&s));
        }
    }

    pub fn top_rule(&self, w: &mut dyn Write) { self.grid_rule(w, '┬') }
    pub fn mid_rule(&self, w: &mut dyn Write) { self.grid_rule(w, '┼') }
    pub fn bot_rule(&self, w: &mut dyn Write) { self.grid_rule(w, '┴') }

    pub fn header_prefix(&self) -> String {
        let mut s = String::new();
        let spaces = self.numw + if self.numw > 0 { 1 } else { 0 } + if self.has_changes { 2 } else { 0 };
        for _ in 0..spaces { s.push(' '); }
        if crate::config::style_has(self.style, StyleComp::Grid) && self.sidebar() > 0 {
            s.push_str(&self.frame_s("│ "));
        }
        s
    }

    pub fn line_prefix(&self, num: Option<usize>, marker: Option<char>, cont: bool) -> String {
        let mut s = String::new();
        if self.numw > 0 && !cont {
            let n = match num { Some(n) => n, None => 0 };
            let mut ns = n.to_string();
            while ns.len() < self.numw { ns.insert(0, ' '); }
            s.push_str(&self.frame_s(&ns));
            s.push(' ');
        } else if self.numw > 0 && cont {
            for _ in 0..self.numw { s.push(' '); }
            s.push(' ');
        } else if self.numw == 0 && cont {
            // no number field
        }
        if self.has_changes {
            let m = match marker { Some(c) => c.to_string(), None => " ".to_string() };
            s.push_str(&self.style_s(self.cfg.marker_color(), &m));
            s.push(' ');
        }
        if crate::config::style_has(self.style, StyleComp::Grid) && self.sidebar() > 0 {
            s.push_str(&self.frame_s("│"));
            s.push(' ');
        }
        s
    }

    pub fn snip_prefix(&self) -> String {
        let cc = self.content_col();
        let grid = crate::config::style_has(self.style, StyleComp::Grid);
        let p = if grid { cc } else { if cc > 0 { cc - 1 } else { 0 } };
        let mut s = String::new();
        if self.numw > 0 {
            let dots = " ...".to_string();
            let mut d = dots;
            while d.len() < self.numw { d.insert(0, ' '); }
            s.push_str(&self.frame_s(&d));
            if p > 4 { for _ in 0..(p - 4 - if self.has_changes { 2 } else { 0 }) { s.push(' '); } }
        }
        // marker field
        if self.has_changes {
            s.push_str(&self.style_s(self.cfg.marker_color(), " "));
            s.push(' ');
        }
        if crate::config::style_has(self.style, StyleComp::Grid) && self.sidebar() > 0 {
            s.push_str(&self.frame_s("│"));
            s.push(' ');
        }
        let _ = p;
        s
    }

    pub fn snip_line(&self) -> String {
        let pre = self.snip_prefix();
        let avail = if self.term_width > pre.chars().count() { self.term_width - pre.chars().count() } else { 0 };
        let k = avail / 2;
        if k == 0 { return pre; }
        let idx = k / 2;
        let mut pat = String::new();
        for i in 0..k {
            if i == idx { pat.push_str("8< "); } else { pat.push_str("─ "); }
        }
        let mut line = pre + &pat;
        while line.ends_with(' ') { line.pop(); }
        line
    }
}
EOF
