use std::io::Write;

pub const LONG_HELP: &str = include_str!("../assets/long-help.txt");
pub const SHORT_HELP: &str = include_str!("../assets/short-help.txt");
pub const LANGUAGES: &str = include_str!("../assets/languages.txt");
pub const THEMES: &str = include_str!("../assets/themes.txt");
pub const COMP_BASH: &str = include_str!("../assets/comp-bash.txt");
pub const COMP_FISH: &str = include_str!("../assets/comp-fish.txt");
pub const COMP_ZSH: &str = include_str!("../assets/comp-zsh.txt");
pub const COMP_PS1: &str = include_str!("../assets/comp-ps1.txt");
pub const ACK: &str = include_str!("../assets/acknowledgements.txt");

pub fn print_help() { print!("{}", LONG_HELP); }
pub fn print_short_help() { print!("{}", SHORT_HELP); }
pub fn list_languages() { print!("{}", LANGUAGES); }
pub fn list_themes() { print!("{}", THEMES); }
pub fn acknowledgements() { print!("{}", ACK); }

pub fn completion(shell: &str) {
    match shell {
        "bash" => print!("{}", COMP_BASH),
        "fish" => print!("{}", COMP_FISH),
        "zsh" => print!("{}", COMP_ZSH),
        "ps1" => print!("{}", COMP_PS1),
        _ => {}
    }
}

pub fn home() -> String { std::env::var("HOME").unwrap_or_else(|_| "/root".to_string()) }

pub fn xdg_config() -> String {
    if let Ok(v) = std::env::var("XDG_CONFIG_HOME") {
        if !v.is_empty() { return v; }
    }
    format!("{}/.config", home())
}
pub fn xdg_cache() -> String {
    if let Ok(v) = std::env::var("XDG_CACHE_HOME") {
        if !v.is_empty() { return v; }
    }
    format!("{}/.cache", home())
}
pub fn config_dir() -> String { format!("{}/bat", xdg_config()) }
pub fn cache_dir() -> String { format!("{}/bat", xdg_cache()) }
pub fn config_file_path() -> String {
    if let Ok(p) = std::env::var("BAT_CONFIG_PATH") {
        if !p.is_empty() { return p; }
    }
    format!("{}/config", config_dir())
}

/// Very small shell-word splitter used for the configuration file.
pub fn shell_words(line: &str) -> Vec<String> {
    let mut out = Vec::new();
    let cs: Vec<char> = line.chars().collect();
    let mut i = 0usize;
    let mut cur = String::new();
    let mut in_word = false;
    while i < cs.len() {
        let c = cs[i];
        if c == ' ' || c == '\t' || c == '\n' {
            if in_word { out.push(std::mem::take(&mut cur)); in_word = false; }
            i += 1;
            continue;
        }
        in_word = true;
        if c == '\'' {
            i += 1;
            while i < cs.len() && cs[i] != '\'' { cur.push(cs[i]); i += 1; }
            i += 1;
        } else if c == '"' {
            i += 1;
            while i < cs.len() && cs[i] != '"' {
                if cs[i] == '\\' && i + 1 < cs.len() && (cs[i+1] == '"' || cs[i+1] == '\\') {
                    i += 1;
                }
                cur.push(cs[i]); i += 1;
            }
            i += 1;
        } else if c == '\\' && i + 1 < cs.len() {
            i += 1; cur.push(cs[i]); i += 1;
        } else {
            cur.push(c); i += 1;
        }
    }
    if in_word { out.push(cur); }
    out
}

