pub fn cache_cmd(argv: &[String]) {
    // replicate the observed `bat cache` behaviour
    let mut build = false;
    let mut clear = false;
    let mut ack = false;
    let mut source: Option<String> = None;
    let mut target: Option<String> = None;
    let mut blank = false;
    let mut help = false;
    let mut i = 0usize;
    let mut positional: Vec<String> = Vec::new();
    while i < argv.len() {
        let a = &argv[i];
        if a == "--" { i += 1; continue; }
        if a.starts_with("--") {
            let (n, v) = match a.find('=') { Some(p) => (a[2..p].to_string(), Some(a[p+1..].to_string())), None => (a[2..].to_string(), None) };
            match n.as_str() {
                "build" => build = true,
                "clear" => clear = true,
                "acknowledgements" => ack = true,
                "blank" => blank = true,
                "source" => { if let Some(v) = v { source = Some(v); } else { i += 1; if i < argv.len() { source = Some(argv[i].clone()); } } }
                "target" => { if let Some(v) = v { target = Some(v); } else { i += 1; if i < argv.len() { target = Some(argv[i].clone()); } } }
                "help" => help = true,
                _ => { eprintln!("error: unexpected argument '--{}' found", n); std::process::exit(2); }
            }
        } else if a.starts_with('-') && a.len() > 1 {
            for c in a[1..].chars() {
                match c {
                    'b' => build = true,
                    'c' => clear = true,
                    'h' => help = true,
                    _ => { eprintln!("error: unexpected argument '-{}' found", c); std::process::exit(2); }
                }
            }
        } else {
            positional.push(a.clone());
        }
        i += 1;
    }
    if help {
        print!("{}", CACHE_HELP);
        return;
    }
    if positional.len() > 0 {
        for p in &positional {
            eprintln!("[bat error]: '{}': No such file or directory (os error 2)", p);
        }
        std::process::exit(1);
    }
    if ack {
        println!("Writing acknowledgements to {} ... okay", crate::info::cache_dir());
        return;
    }
    if clear {
        let d = crate::info::cache_dir();
        println!("Clearing theme set cache ... {}", ok_or(&format!("{}/themes.bin", d)));
        println!("Clearing syntax set cache ... {}", ok_or(&format!("{}/syntaxes.bin", d)));
        println!("Clearing metadata file ... {}", ok_or(&format!("{}/metadata.yaml", d)));
        let _ = std::fs::create_dir_all(&d);
        let _ = std::fs::remove_file(format!("{}/themes.bin", d));
        let _ = std::fs::remove_file(format!("{}/syntaxes.bin", d));
        let _ = std::fs::remove_file(format!("{}/metadata.yaml", d));
        return;
    }
    if build {
        let sd = source.unwrap_or_else(|| crate::info::config_dir());
        let td = target.unwrap_or_else(|| crate::info::cache_dir());
        if crate::syntax::custom_syntax_count(&sd) == 0 {
            println!("No syntaxes were found in '{}/syntaxes', using the default set.", sd);
        }
        if crate::theme::custom_theme_count(&sd) == 0 {
            println!("No themes were found in '{}/themes', using the default set", sd);
        }
        let _ = std::fs::create_dir_all(&td);
        let mut f = std::fs::File::create(format!("{}/themes.bin", td)).unwrap();
        let _ = f.write_all(b"\x00\x00\x00\x00");
        println!("Writing theme set to {}/themes.bin ... okay", td);
        let mut f = std::fs::File::create(format!("{}/syntaxes.bin", td)).unwrap();
        let _ = f.write_all(b"\x00\x00\x00\x00");
        println!("Writing syntax set to {}/syntaxes.bin ... okay", td);
        let _ = std::fs::write(format!("{}/metadata.yaml", td), "acknowledgements: 0\nsyntaxes: 0\nthemes: 28\nversion: 1\n");
        println!("Writing metadata to folder {} ... okay", td);
    }
}

fn ok_or(p: &str) -> &'static str {
