    s.push_str("#### Command-line\n\n```bash\n");
    let mut cmd = std::env::args().collect::<Vec<_>>().join(" ");
    cmd.push(' ');
    s.push_str(&format!("{}\n```\n\n", cmd));
    s.push_str("#### Environment variables\n\n```bash\n");
    for v in ["BAT_CACHE_PATH","BAT_CONFIG_PATH","BAT_OPTS","BAT_PAGER","BAT_PAGING","BAT_STYLE","BAT_TABS","BAT_THEME","BAT_WIDTH","BAT_THEME_DARK","BAT_THEME_LIGHT","COLORTERM","LANG","LC_ALL","LESS","MANPAGER","NO_COLOR","PAGER","SHELL","TERM","XDG_CACHE_HOME","XDG_CONFIG_HOME"] {
        match std::env::var(v) {
            Ok(val) => s.push_str(&format!("{}={}\n", v, val)),
            Err(_) => s.push_str(&format!("{}=<not set>\n", v)),
        }
    }
    s.push_str("```\n\n");
    // system config
    s.push_str("#### System Config file\n\n");
    match std::fs::read_to_string("/etc/bat/config") {
        Ok(c) => s.push_str(&format!("```\n{}\n```\n\n", c)),
        Err(e) => s.push_str(&format!("Could not read contents of '/etc/bat/config': {}.\n\n", e)),
    }
    s.push_str("#### Config file\n\n");
    let cp = config_file_path();
    match std::fs::read_to_string(&cp) {
        Ok(c) => s.push_str(&format!("```\n{}\n```\n\n", c)),
        Err(e) => s.push_str(&format!("Could not read contents of '{}': {}.\n\n", cp, e)),
    }
    s.push_str("#### Custom assets metadata\n\n");
    let md = format!("{}/metadata.yaml", crate::info::cache_dir());
    match std::fs::read_to_string(&md) {
        Ok(c) => s.push_str(&format!("```\n{}\n```\n\n", c)),
        Err(e) => s.push_str(&format!("Could not read contents of '{}': {}.\n\n", md, e)),
    }
    s.push_str("#### Custom assets\n\n");
    let cd = crate::info::cache_dir();
    match std::fs::read_dir(&cd) {
        Ok(mut it) => {
            if it.next().is_none() {
                s.push_str(&format!("'{}' is empty\n\n", cd));
            } else {
                s.push_str(&format!("'{}' found\n\n", cd));
            }
        }
        Err(_) => s.push_str(&format!("'{}' not found\n\n", cd)),
    }
    s.push_str("#### Detected terminal color scheme\n\nnot detected\n\n");
    s.push_str("#### Compile time information\n\n- Profile: release\n- Target triple: x86_64-unknown-linux-gnu\n- Family: unix\n- OS: linux\n- Architecture: x86_64\n- Pointer width: 64\n- Endian: little\n- CPU features: fxsr,sse,sse2\n- Host: x86_64-unknown-linux-gnu\n\n");
    s.push_str("#### Less version\n\n```\n");
    let pager = pager_prog();
    match run_pager_version(&pager) {
        Ok(out) => s.push_str(&format!("> {} --version \n{}\n```\n\n\n", pager, out)),
        Err(e) => s.push_str(&format!("Could not run command '{}': {}\n\n\n", pager, e)),
    }
    print!("{}", s);
}

fn run_pager_version(prog: &str) -> Result<String, String> {
    use std::process::{Command, Stdio};
    match Command::new(prog).arg("--version").stderr(Stdio::piped()).output() {
        Ok(o) => {
            let mut s = String::from_utf8_lossy(&o.stdout).to_string();
            while s.ends_with('\n') { s.pop(); }
            Ok(s)
        }
        Err(e) => Err(format!("{}", e)),
    }
}

fn pager_prog() -> String {
    if let Ok(p) = std::env::var("BAT_PAGER") {
        if !p.is_empty() { return first_word(&p); }
    }
    if let Ok(p) = std::env::var("PAGER") {
        if !p.is_empty() { return first_word(&p); }
    }
    "less".to_string()
}

fn first_word(s: &str) -> String {
    s.split_whitespace().next().unwrap_or("").to_string()
}

fn os_info() -> (String, String) {
    let mut name = String::from("Linux");
    if let Ok(c) = std::fs::read_to_string("/etc/os-release") {
        let mut n = String::new();
        let mut v = String::new();
        for line in c.lines() {
            if let Some(r) = line.strip_prefix("NAME=") { n = r.trim_matches('"').to_string(); }
            if let Some(r) = line.strip_prefix("VERSION_ID=") { v = r.trim_matches('"').to_string(); }
        }
        if !n.is_empty() {
            name = if v.is_empty() { n } else { format!("{} ({})", n, format!("{} {}", n, v)) };
            name = format!("{} ({})", n, v);
        }
    }
    let mut kernel = String::new();
    if let Ok(c) = std::fs::read_to_string("/proc/sys/kernel/osrelease") {
        kernel = c.trim().to_string();
    }
    (name, kernel)
}
