fn run_pager_version(prog: &str) -> Result<String, String> {
    use std::process::{Command, Stdio};
    match Command::new(prog).arg("--version").stderr(Stdio::piped()).output() {
        Ok(o) => {
            let mut s = String::from_utf8_lossy(&o.stdout).to_string();
            while s.ends_with('\n') { s.pop(); }
