        for line in c.lines() {
            if let Some(r) = line.strip_prefix("NAME=") { n = r.trim_matches('"').to_string(); }
            if let Some(r) = line.strip_prefix("VERSION_ID=") { v = r.trim_matches('"').to_string(); }
        }
        if !n.is_empty() {
            name = if v.is_empty() { n } else { format!("{} ({})", n, format!("{} {}", n, v)) };
            name = format!("{} ({})", n, v);
        }
    }
    let mut kernel = String::new();
    if let Ok(c) = std::fs::read_to_string("/proc/sys/kernel/osrelease") {
        kernel = c.trim().to_string();
    }
    (name, kernel)
}
