/// Very small shell-word splitter used for the configuration file.
pub fn shell_words(line: &str) -> Vec<String> {
    let mut out = Vec::new();
    let cs: Vec<char> = line.chars().collect();
    let mut i = 0usize;
    let mut cur = String::new();
    let mut in_word = false;
    while i < cs.len() {
        let c = cs[i];
        if c == ' ' || c == '\t' || c == '\n' {
            if in_word { out.push(std::mem::take(&mut cur)); in_word = false; }
            i += 1;
            continue;
        }
        in_word = true;
        if c == '\'' {
            i += 1;
            while i < cs.len() && cs[i] != '\'' { cur.push(cs[i]); i += 1; }
            i += 1;
        } else if c == '"' {
            i += 1;
            while i < cs.len() && cs[i] != '"' {
                if cs[i] == '\\' && i + 1 < cs.len() && (cs[i+1] == '"' || cs[i+1] == '\\') {
                    i += 1;
                }
                cur.push(cs[i]); i += 1;
            }
            i += 1;
        } else if c == '\\' && i + 1 < cs.len() {
            i += 1; cur.push(cs[i]); i += 1;
        } else {
            cur.push(c); i += 1;
        }
    }
    if in_word { out.push(cur); }
    out
}

