import subprocess,re,json
themes=[l.strip() for l in open('assets/themes.txt') if l.strip()]
def segs(args):
    p=subprocess.run(args,capture_output=True)
    out=p.stdout.decode('utf8','replace')
    parts=re.split(r'(\x1b\[[0-9;]*m)',out)
    r=[];cur=''
    for x in parts:
        if x.startswith('\x1b['): cur=x[2:-1]
        elif x: r.append((cur,x))
    return r
pairs=set()
for t in themes:
    a=segs(['./executable','--color=always','--decorations=never','--theme='+t,'-l','python','/tmp/p.py'])
    b=segs(['./executable','--color=always','--decorations=never','--theme='+t,'-l','python','/tmp/p.py','--italic-text=always'])
    tc=[];c256=[]
    for (s,x) in a:
        m=re.match(r'38;2;(\d+);(\d+);(\d+)',s)
        if m: tc.append((int(m.group(1)),int(m.group(2)),int(m.group(3))))
        m2=re.match(r'(38;5;)(\d+)',s)
        if m2: c256.append(int(m2.group(2)))
    for (s,x) in b:
        m2=re.match(r'(38;5;)(\d+)',s)
    p=subprocess.run(['./executable','--color=always','--decorations=never','--theme='+t,'-l','python','/tmp/p.py'],capture_output=True,env={'COLORTERM':'truecolor','PATH':'/usr/bin'})
    out=p.stdout.decode('utf8','replace')
    parts=re.split(r'(\x1b\[[0-9;]*m)',out)
    r=[];cur=''
    for x in parts:
        if x.startswith('\x1b['): cur=x[2:-1]
        elif x: r.append((cur,x))
    tcv=[s for s,x in r if s.startswith('38;2')]
    p2=subprocess.run(['./executable','--color=always','--decorations=never','--theme='+t,'-l','python','/tmp/p.py'],capture_output=True,env={'PATH':'/usr/bin'})
    out2=p2.stdout.decode('utf8','replace')
    parts=re.split(r'(\x1b\[[0-9;]*m)',out2)
    r2=[];cur=''
    for x in parts:
        if x.startswith('\x1b['): cur=x[2:-1]
        elif x: r2.append((cur,x))
    c256v=[s for s,x in r2 if s.startswith('38;5')]
    if len(tcv)==len(c256v):
        for s1,s2 in zip(tcv,c256v):
            m=re.match(r'38;2;(\d+);(\d+);(\d+)',s1); m2=re.match(r'38;5;(\d+)',s2)
            if m and m2: pairs.add(((int(m.group(1)),int(m.group(2)),int(m.group(3))),int(m2.group(1))))
    else:
        print('MISMATCH',t,len(tcv),len(c256v))
json.dump(sorted([list(map(list,p)) for p in pairs]),open('/tmp/pairs.json','w'))
print(len(pairs))
for p in sorted(pairs)[:20]: print(p)
