{"command": "cd /workspace; cat > /tmp/test256.py <<'PY'
import json
pairs=[((r,g,b),c) for (r,g,b),c in json.load(open('/tmp/pairs.json'))]
# build xterm palette
pal=[]
for i in range(16): pal.append(None)
base=[0,95,135,175,215,255]
for r in range(6):
  for g in range(6):
    for b in range(6):
      pal.append((base[r],base[g],base[b]))
for i in range(24):
  v=8+10*i
  pal.append((v,v,v))
def dist(a,b,w=(1,1,1)): return sum(wi*(x-y)**2 for wi,x,y in zip(w,a,b))
def nearest(rgb,w):
    best=None;bd=1e9
    for i,p in enumerate(pal):
        if p is None: continue
        d=dist(rgb,p,w)
        if d<bd: bd=d;best=i
    return best
def cube(rgb):
    r,g,b=rgb
    qr=round(r/255*5); qg=round(g/255*5); qb=round(b/255*5)
    return 16+36*qr+6*qg+qb
for name,w in [('w111',(1,1,1)),('w243',(2,4,3)),('w124',(1,2,4)),('w213',(2,1,3))]:
    bad=[(rgb,c,nearest(rgb,w)) for rgb,c in pairs if nearest(rgb,w)!=c]
    print(name,'bad',len(bad),'/',len(pairs), bad[:6])
bad=[(rgb,c,cube(rgb)) for rgb,c in pairs if cube(rgb)!=c]
print('cube bad',len(bad),'/',len(pairs), bad[:6])
