{"command": "cd /workspace; cat > /tmp/fit.py <<'PY'
import json,itertools
pairs=[((r,g,b),c) for (r,g,b),c in json.load(open('/tmp/pairs.json'))]
pal=[]
base=[0,95,135,175,215,255]
cube={}
for r in range(6):
  for g in range(6):
    for b in range(6):
      cube[16+36*r+6*g+b]=(base[r],base[g],base[b])
gray={232+i:(8+10*i,)*3 for i in range(24)}
def best(rgb,w):
    r,g,b=rgb
    bd=1e18;bi=None
    for i,p in list(cube.items())+list(gray.items()):
        d=w[0]*(r-p[0])**2+w[1]*(g-p[1])**2+w[2]*(b-p[2])**2
        if d<bd: bd=d;bi=i
    return bi
bestres=None
import numpy as np
for wr in np.arange(0.5,6.01,0.25):
  for wg in np.arange(0.5,6.01,0.25):
    for wb in np.arange(0.5,6.01,0.25):
        bad=sum(1 for rgb,c in pairs if best(rgb,(wr,wg,wb))!=c)
        if bad==0:
            print('PERFECT',wr,wg,wb); bestres=(wr,wg,wb); break
        if bestres is None or bad<bestres[0]:
            bestres=(bad,wr,wg,wb)
    if bestres and bestres[0]==0: break
  if bestres and bestres[0]==0: break
print('best',bestres)
