/// RGB to 256-colour conversion (derived empirically).
pub fn rgb_to_256(r: u8, g: u8, b: u8) -> u8 {
    let pal: [(u8, u8, u8); 240] = {
        let mut p = [(0u8, 0u8, 0u8); 240];
        let base = [0u8, 95, 135, 175, 215, 255];
        let mut i = 0;
        for rr in 0..6 { for gg in 0..6 { for bb in 0..6 {
            p[i] = (base[rr], base[gg], base[bb]); i += 1;
        } } }
        for k in 0..24 { let v = 8 + 10 * k as u8; p[i + k] = (v, v, v); }
        p
    };
    let mut best = 0u8; let mut bd = i64::MAX;
    for (i, (pr, pg, pb)) in pal.iter().enumerate() {
        let dr = r as i64 - *pr as i64;
        let dg = g as i64 - *pg as i64;
        let db = b as i64 - *pb as i64;
        let d = dr * dr + dg * dg + db * db;
        if d < bd { bd = d; best = i as u8; }
    }
    best
}
