pub static SYNTAXES: &[Syntax] = &[ include!("syntax_table.rs") ][0];

pub fn syntax_count(cfg_dir: &str) -> usize {
    let _ = cfg_dir;
    SYNTAXES.len()
}
pub fn custom_syntax_count(_dir: &str) -> usize { 0 }
