use crate::config::*;
use std::io::Write;
use std::process::{Command, Stdio};

pub fn command(cfg: &Config) -> String {
    if let Some(p) = &cfg.pager { return p.clone(); }
    if let Ok(p) = std::env::var("BAT_PAGER") {
        if !p.is_empty() { return p; }
    }
    if let Ok(p) = std::env::var("PAGER") {
        if !p.is_empty() { return p; }
    }
    "less -R -K".to_string()
}

pub fn spawn(cmd: &str) -> Option<Box<dyn Write>> {
    let words: Vec<&str> = cmd.split_whitespace().collect();
    if words.is_empty() { return None; }
    let prog = words[0];
    let args = if words.len() > 1 { &words[1..] } else { &[] };
    let mut child = match Command::new(prog)
        .args(args)
        .stdin(Stdio::piped())
        .spawn() {
        Ok(c) => c,
        Err(_) => return None,
    };
    let stdin = child.stdin.take()?;
    std::mem::forget(child);
    Some(Box::new(ChildIn { stdin }))
}

struct ChildIn { stdin: std::process::ChildStdin }
impl Write for ChildIn {
    fn write(&mut self, buf: &[u8]) -> std::io::Result<usize> { self.stdin.write(buf) }
    fn flush(&mut self) -> std::io::Result<()> { self.stdin.flush() }
}

pub fn decide(cfg: &Config) -> Tri {
    if let Ok(v) = std::env::var("BAT_PAGING") {
        match v.as_str() {
            "never" => return Tri::Never,
            "always" => return Tri::Always,
            "auto" => return Tri::Auto,
            _ => {}
        }
    }
    cfg.paging
}
