struct M<'a> { s: &'a [char], ic: bool }

fn eq(a: char, b: char, ic: bool) -> bool { if ic { a.to_lowercase().eq(b.to_lowercase()) } else { a == b } }

fn class_match(neg: bool, items: &[ClassItem], c: char, ic: bool) -> bool {
    let mut hit = false;
    for it in items {
        let m = match it {
            ClassItem::Ch(x) => eq(*x, c, ic),
            ClassItem::Range(a, b) => (c >= *a && c <= *b) || (ic && c.to_lowercase().next().map(|l| l >= *a && l <= *b).unwrap_or(false)),
            ClassItem::Digit => c.is_ascii_digit(),
            ClassItem::NotDigit => !c.is_ascii_digit(),
            ClassItem::Word => c.is_alphanumeric() || c == '_',
            ClassItem::NotWord => !(c.is_alphanumeric() || c == '_'),
            ClassItem::Space => c.is_whitespace(),
            ClassItem::NotSpace => !c.is_whitespace(),
            ClassItem::Alpha => c.is_alphabetic(),
            ClassItem::Upper => c.is_uppercase(),
            ClassItem::Lower => c.is_lowercase(),
            ClassItem::Alnum => c.is_alphanumeric(),
            ClassItem::Punct => c.is_ascii_punctuation(),
            ClassItem::Print => c.is_ascii_graphic() || c == ' ',
            ClassItem::Graph => c.is_ascii_graphic(),
            ClassItem::Hex => c.is_ascii_hexdigit(),
            ClassItem::Escape => !c.is_alphanumeric(),
        };
        if m { hit = true; break; }
    }
    hit != neg
}

/// Try to match `node` starting at position `pos`; returns the end position.
pub fn find_at(re: &Regex, s: &[char], pos: usize) -> Option<usize> {
    let mut m = M { s, ic: re.icase };
    let n = s.len();
    for p in pos..=n {
        if let Some(e) = mt(&re.node, &mut m, p, &mut |_e| true) {
            return Some(e);
        }
    }
    None
}

/// Match anchored at pos.
pub fn match_at(re: &Regex, s: &[char], pos: usize) -> Option<usize> {
    let mut m = M { s, ic: re.icase };
    mt(&re.node, &mut m, pos, &mut |_e| true)
}

pub fn is_word(c: char) -> bool { c.is_alphanumeric() || c == '_' }

fn mt(node: &Node, m: &mut M, pos: usize, k: &mut dyn FnMut(usize) -> bool) -> Option<usize> {
    match node {
        Node::Empty => { if k(pos) { Some(pos) } else { None } }
        Node::Char(c) => {
            if pos < m.s.len() && eq(*c, m.s[pos], m.ic) { if k(pos + 1) { Some(pos + 1) } else { None } } else { None }
        }
        Node::Any => {
            if pos < m.s.len() && m.s[pos] != '\n' { if k(pos + 1) { Some(pos + 1) } else { None } } else { None }
        }
        Node::Class { neg, items } => {
            if pos < m.s.len() && class_match(*neg, items, m.s[pos], m.ic) { if k(pos + 1) { Some(pos + 1) } else { None } } else { None }
        }
        Node::Start => { if pos == 0 { if k(pos) { Some(pos) } else { None } } else { None } }
        Node::Anchor => { if pos == 0 { if k(pos) { Some(pos) } else { None } } else { None } }
        Node::End => { if pos == m.s.len() { if k(pos) { Some(pos) } else { None } } else { None } }
        Node::WordBoundary => {
            let a = pos > 0 && is_word(m.s[pos - 1]);
            let b = pos < m.s.len() && is_word(m.s[pos]);
            if a != b { if k(pos) { Some(pos) } else { None } } else { None }
        }
        Node::NotWordBoundary => {
            let a = pos > 0 && is_word(m.s[pos - 1]);
            let b = pos < m.s.len() && is_word(m.s[pos]);
            if a == b { if k(pos) { Some(pos) } else { None } } else { None }
        }
