        Node::Alt(v) => {
            for n in v {
                if let Some(e) = mt(n, m, pos, k) { return Some(e); }
            }
            None
        }
        Node::Repeat { node, min, max, greedy } => rep_match(node, *min, *max, *greedy, m, pos, k),
    }
}

fn concat_match(v: &[Node], idx: usize, m: &mut M, pos: usize, k: &mut dyn FnMut(usize) -> bool) -> Option<usize> {
