fn parse_alt(cs: &[char], i: &mut usize, ic: &mut bool, stop: Option<char>) -> Node {
    let mut alts = Vec::new();
    let mut cur: Vec<Node> = Vec::new();
    while *i < cs.len() {
        let c = cs[*i];
        if Some(c) == stop { break; }
        if c == '|' { *i += 1; alts.push(concat(std::mem::take(&mut cur))); continue; }
        cur.push(parse_one(cs, i, ic, stop));
    }
    if !cur.is_empty() { alts.push(concat(cur)); }
    if alts.len() == 1 { alts.pop().unwrap() } else { Node::Alt(alts) }
}

