                    *i = j + 1;
                    let mut k = *i;
                    let n = parse_alt(cs, &mut k, ic, Some(')'));
                    *i = k + 1;
                    return Node::Look { node: Box::new(n), neg: inner.starts_with('!') };
                }
                *i = j + 1;
                let mut k = *i;
                let n = parse_alt(cs, &mut k, ic, Some(')'));
                *i = k + 1;
                return Node::Group(Box::new(n));
