fn eq(a: char, b: char, ic: bool) -> bool {
    if ic { a.to_lowercase().eq(b.to_lowercase()) } else { a == b }
}

fn class_match(neg: bool, items: &[ClassItem], c: char, ic: bool) -> bool {
    let mut hit = false;
    for it in items {
        let m = match it {
            ClassItem::Ch(x) => eq(*x, c, ic),
            ClassItem::Range(a, b) => (c >= *a && c <= *b) || (ic && c.to_lowercase().next().map(|l| l >= *a && l <= *b).unwrap_or(false)),
            ClassItem::Digit => c.is_ascii_digit(),
            ClassItem::NotDigit => !c.is_ascii_digit(),
            ClassItem::Word => c.is_alphanumeric() || c == '_',
            ClassItem::NotWord => !(c.is_alphanumeric() || c == '_'),
            ClassItem::Space => c.is_whitespace(),
            ClassItem::NotSpace => !c.is_whitespace(),
            ClassItem::Alpha => c.is_alphabetic(),
            ClassItem::Upper => c.is_uppercase(),
            ClassItem::Lower => c.is_lowercase(),
            ClassItem::Alnum => c.is_alphanumeric(),
            ClassItem::Punct => c.is_ascii_punctuation(),
            ClassItem::Print => c.is_ascii_graphic() || c == ' ',
            ClassItem::Graph => c.is_ascii_graphic(),
            ClassItem::Hex => c.is_ascii_hexdigit(),
            ClassItem::Escape => !c.is_alphanumeric(),
        };
        if m { hit = true; break; }
    }
    hit != neg
}

pub fn is_word(c: char) -> bool { c.is_alphanumeric() || c == '_' }

struct Ctx<'a> { s: &'a [char], ic: bool }

fn mt(node: &Node, c: &Ctx, pos: usize, k: &dyn Fn(usize) -> bool) -> bool {
    match node {
        Node::Empty => k(pos),
        Node::Char(ch) => pos < c.s.len() && eq(*ch, c.s[pos], c.ic) && k(pos + 1),
        Node::Any => pos < c.s.len() && c.s[pos] != '\n' && k(pos + 1),
        Node::Class { neg, items } => pos < c.s.len() && class_match(*neg, items, c.s[pos], c.ic) && k(pos + 1),
        Node::Start | Node::Anchor => pos == 0 && k(pos),
        Node::End => pos == c.s.len() && k(pos),
        Node::WordBoundary => {
            let a = pos > 0 && is_word(c.s[pos - 1]);
            let b = pos < c.s.len() && is_word(c.s[pos]);
            (a != b) && k(pos)
        }
        Node::NotWordBoundary => {
            let a = pos > 0 && is_word(c.s[pos - 1]);
            let b = pos < c.s.len() && is_word(c.s[pos]);
            (a == b) && k(pos)
        }
        Node::Group(inner) => mt(inner, c, pos, k),
        Node::Look { node, neg } => {
            let hit = mt(node, c, pos, &|_| true);
            (hit != *neg) && k(pos)
        }
        Node::Concat(v) => concat_match(v, 0, c, pos, k),
        Node::Alt(v) => v.iter().any(|n| mt(n, c, pos, k)),
        Node::Repeat { node, min, max, greedy } => {
            if *greedy { rep_max(node, *min, *max, c, pos, 0, k) } else { rep_min(node, *min, *max, c, pos, 0, k) }
        }
    }
}

fn concat_match(v: &[Node], idx: usize, c: &Ctx, pos: usize, k: &dyn Fn(usize) -> bool) -> bool {
    if idx == v.len() { return k(pos); }
    mt(&v[idx], c, pos, &|p2| concat_match(v, idx + 1, c, p2, k))
}

fn rep_max(node: &Node, min: u32, max: Option<u32>, c: &Ctx, pos: usize, count: u32, k: &dyn Fn(usize) -> bool) -> bool {
    let can_more = max.map(|m| count < m).unwrap_or(true);
    if can_more && mt(node, c, pos, &|p| p != pos && rep_max(node, min, max, c, p, count + 1, k)) { return true; }
    if count >= min { return k(pos); }
    false
}

fn rep_min(node: &Node, min: u32, max: Option<u32>, c: &Ctx, pos: usize, count: u32, k: &dyn Fn(usize) -> bool) -> bool {
    if count >= min && k(pos) { return true; }
    let can_more = max.map(|m| count < m).unwrap_or(true);
    can_more && mt(node, c, pos, &|p| p != pos && rep_min(node, min, max, c, p, count + 1, k))
}

/// Leftmost match starting at or after `pos`. Returns (start, end).
pub fn find_from(re: &Regex, s: &[char], pos: usize) -> Option<(usize, usize)> {
    let c = Ctx { s, ic: re.icase };
    let n = s.len();
    for p in pos..=n {
        let mut end: Option<usize> = None;
        let ok = mt(&re.node, &c, p, &|e| { end = Some(e); true });
        if ok {
            return Some((p, end.unwrap_or(p)));
        }
    }
    None
}

/// Anchored match at pos; returns end.
pub fn match_at(re: &Regex, s: &[char], pos: usize) -> Option<usize> {
    let c = Ctx { s, ic: re.icase };
    let mut end: Option<usize> = None;
    let ok = mt(&re.node, &c, pos, &|e| { end = Some(e); true });
    if ok { Some(end.unwrap_or(pos)) } else { None }
}
