/// Wrap atoms into lines of at most `width` display columns.
pub fn wrap_atoms(atoms: &[Atom], width: usize, word: bool) -> Vec<Vec<Atom>> {
    if width == 0 { return vec![atoms.to_vec()]; }
    let mut lines: Vec<Vec<Atom>> = Vec::new();
    let mut cur: Vec<Atom> = Vec::new();
    let mut curw = 0usize;
    if !word {
        for a in atoms {
            let mut text = String::new();
            let mut w = 0usize;
            for ch in a.text.chars() {
                let cw = crate::wrap::char_width(ch);
                if curw + w + cw > width && w > 0 {
                    cur.push(Atom { style: a.style, text: std::mem::take(&mut text), w });
                    lines.push(std::mem::take(&mut cur));
                    curw = 0;
                }
                text.push(ch);
                w += cw;
            }
            if !text.is_empty() {
                cur.push(Atom { style: a.style, text, w });
                curw += w;
            }
            if curw > width {
                lines.push(std::mem::take(&mut cur));
                curw = 0;
            }
        }
        if !cur.is_empty() || lines.is_empty() { lines.push(cur); }
        return lines;
    }
    // word mode
    for a in atoms {
        let mut cur_text = String::new();
        let mut cur_w = 0usize;
        let mut pending_word = String::new();
        let mut pending_w = 0usize;
        let chs: Vec<char> = a.text.chars().collect();
        let mut i = 0usize;
        while i < chs.len() {
            let ch = chs[i];
            if ch == ' ' {
                if !pending_word.is_empty() {
                    let need = curw + (if !cur.is_empty() { 1 } else { 0 }) + pending_w;
                    if need > width && !cur.is_empty() {
                        lines.push(std::mem::take(&mut cur));
                        curw = 0;
                    } else if !cur.is_empty() {
                        cur.push(Atom { style: a.style, text: " ".to_string(), w: 1 });
                        curw += 1;
                    }
                    cur.push(Atom { style: a.style, text: std::mem::take(&mut pending_word), w: pending_w });
                    curw += pending_w;
                    pending_word.clear(); pending_w = 0;
                }
                cur_text.push(ch);
                cur_w += 1;
                i += 1;
                // spaces accumulate in cur_text
                continue;
            }
            // accumulate a word
            while i < chs.len() && chs[i] != ' ' {
                pending_word.push(chs[i]);
                pending_w += crate::wrap::char_width(chs[i]);
                i += 1;
            }
            if curw + (if !cur.is_empty() { 1 } else { 0 }) + pending_w <= width {
                if !cur.is_empty() && !cur_text.is_empty() {
                    cur.push(Atom { style: a.style, text: std::mem::take(&mut cur_text), w: cur_w });
                    curw += cur_w;
                    cur_w = 0;
                }
                continue;
            } else {
                // break the line
                if !cur_text.is_empty() { cur.push(Atom { style: a.style, text: std::mem::take(&mut cur_text), w: cur_w }); curw += cur_w; cur_w = 0; }
                if !cur.is_empty() { lines.push(std::mem::take(&mut cur)); curw = 0; }
                if pending_w > width {
                    // hard break
                    let mut w = 0usize;
                    let mut buf = String::new();
                    for c in pending_word.chars() {
                        let cw = crate::wrap::char_width(c);
                        if w + cw > width && w > 0 { cur.push(Atom { style: a.style, text: std::mem::take(&mut buf), w }); lines.push(std::mem::take(&mut cur)); w = 0; }
                        buf.push(c); w += cw;
                    }
                    pending_word = buf; pending_w = w;
                }
            }
        }
        if !cur_text.is_empty() { cur.push(Atom { style: a.style, text: std::mem::take(&mut cur_text), w: cur_w }); curw += cur_w; }
        if !pending_word.is_empty() { cur.push(Atom { style: a.style, text: pending_word, w: pending_w }); curw += pending_w; }
        if curw > width { lines.push(std::mem::take(&mut cur)); curw = 0; }
    }
    if !cur.is_empty() || lines.is_empty() { lines.push(cur); }
    lines
}

pub fn newline_atom(show_all: bool, style: u32) -> Option<Atom> {
    if show_all { Some(Atom { style, text: "\u{240a}".to_string(), w: 1 }) } else { None }
}
