// style ids used by languages; resolved per (theme, lang) from the generated table
pub const PLAIN: u32 = 0;

pub struct StyleMap { pub codes: Vec<(&'static str, &'static str)> } // (256, tc)

pub fn styles_for(lang: &str, theme: &str) -> Option<&'static crate::style_table::ThemeLangStyles> {
