        .find(|t| t.theme == theme && t.lang.eq_ignore_ascii_case(lang))
}

pub fn lookup(lang: &str, theme: &str, style: u32, tc: bool) -> String {
    let def: &[(u32, &str, &str)] = &[];
    let codes = styles_for(lang, theme).map(|t| t.codes).unwrap_or(def);
    for (id, c256, ctc) in codes {
        if *id == style { return if tc { ctc.to_string() } else { c256.to_string() }; }
    }
    String::new()
}

