/// Tokenize a line; returns (style, text) tokens.
pub fn tokenize(lang: &Lang, line: &str, state: &mut usize) -> Vec<(u32, String)> {
    let chars: Vec<char> = line.chars().collect();
    let mut out: Vec<(u32, String)> = Vec::new();
    let mut pos = 0usize;
    let mut plain = String::new();
    let n = chars.len();
    let mut guard = 0usize;
    while pos < n {
        guard += 1;
        if guard > 20000 { break; }
        let mut matched = false;
        'outer: for &ri in &lang.states[*state] {
            let rule = &lang.rules[ri];
            let re = &lang.resolved[ri];
            if let Some(end) = crate::re::match_at(re, &chars, pos) {
                if end == pos { continue; }
                if !plain.is_empty() {
                    out.push((PLAIN, std::mem::take(&mut plain)));
                }
                let text: String = chars[pos..end].iter().collect();
                out.push((rule.kind, text));
                if rule.push >= 0 { *state = rule.push as usize; }
                else if rule.push == -1 { /* pop handled by caller state machine */ }
                if rule.pop { if *state > 0 { *state = 0; } }
                pos = end;
                matched = true;
                break 'outer;
            }
        }
        if !matched {
            plain.push(chars[pos]);
            pos += 1;
        }
    }
    if !plain.is_empty() { out.push((PLAIN, plain)); }
    out
}

