// Language definitions: file-extension table (from the observed --list-languages output)
// plus hand-written highlighters.
pub use crate::syntax_list::*;
use crate::hl::Lang;

pub struct SyntaxInfo { pub name: &'static str, pub exts: &'static str }

pub fn by_name(name: &str) -> Option<&'static Lang> {
    LANGS.iter().find(|l| l.name.eq_ignore_ascii_case(name)).map(|l| &**l)
}

pub fn by_token(tok: &str) -> Option<&'static Lang> {
    let t = tok.to_lowercase();
    for l in LANGS.iter() {
        if l.name.eq_ignore_ascii_case(tok) { return Some(&**l); }
    }
    for l in LANGS.iter() {
        for e in l.exts.split(',') {
            if e.eq_ignore_ascii_case(&t) { return Some(&**l); }
        }
    }
    None
}

pub fn find_for_filename(fname: &str) -> Option<&'static Lang> {
    let base = fname.rsplit('/').next().unwrap_or(fname);
    // exact filename match first
    for l in LANGS.iter() {
        for e in l.exts.split(',') {
            if e.eq_ignore_ascii_case(base) { return Some(&**l); }
        }
    }
    // extension match
    let ext = if let Some(p) = base.rfind('.') { &base[p + 1..] } else { return None };
    for l in LANGS.iter() {
        for e in l.exts.split(',') {
            if e.eq_ignore_ascii_case(ext) { return Some(&**l); }
        }
    }
    None
}

pub fn all_syntax_info() -> Vec<SyntaxInfo> {
    LANG_LIST.iter().map(|(n, e)| SyntaxInfo { name: *n, exts: *e }).collect()
}
