use crate::config::*;
use crate::out::Printer;
use crate::hl::{Atom, Lang};
use std::io::Write;

pub struct Source {
    pub lines: Vec<String>,
    pub total: usize,
    pub size: usize,
    pub empty: bool,
    pub binary: bool,
    pub name: String,
}

pub fn io_err(e: &std::io::Error) -> String {
    match e.raw_os_error() {
        Some(2) => "No such file or directory (os error 2)".to_string(),
        Some(13) => "Permission denied (os error 13)".to_string(),
        Some(21) => "Is a directory (os error 21)".to_string(),
        _ => format!("{}", e),
    }
}

pub fn make_source(bytes: &[u8], name: &str) -> Source {
    let text = String::from_utf_lossy(bytes).to_string();
    let binary = bytes[..bytes.len().min(1024)].contains(&0u8);
    let mut lines: Vec<String> = text.split('\n').map(|s| s.to_string()).collect();
    if lines.last().map(|s| s.is_empty()).unwrap_or(false) { lines.pop(); }
    Source { total: lines.len(), size: bytes.len(), empty: bytes.is_empty(), binary,
             name: name.to_string(), lines }
}

pub fn read_file(path: &str) -> Result<Source, String> {
    match std::fs::metadata(path) {
        Err(e) => return Err(format!("'{}': {}\n", path, io_err(&e))),
        Ok(m) => { if m.is_dir() { return Err(format!("'{}' is a directory.\n", path)); } }
    }
    match std::fs::read(path) {
        Ok(b) => Ok(make_source(&b, path)),
        Err(e) => Err(format!("'{}': {}\n", path, io_err(&e))),
    }
}

/// resolved display ranges (1-based inclusive)
#[derive(Clone, Copy)]
pub enum RangeSpec { Lines(usize, usize), Only(usize), From(usize), To(usize), LastN(usize), Plus(usize, usize), Ctx(usize, usize), LinesCtx(usize, usize, usize) }

pub fn resolve_ranges(cfg: &Config, total: usize) -> Vec<(usize, usize)> {
    let mut out: Vec<(usize, usize)> = Vec::new();
    if cfg.line_ranges.is_empty() {
        if total > 0 { out.push((1, total)); }
        return out;
    }
    for r in &cfg.line_ranges {
        let (s, e) = match r.spec {
            RangeSpec::Lines(a, b) => (Some(a), Some(b)),
            RangeSpec::Only(a) => (Some(a), Some(a)),
            RangeSpec::From(a) => (Some(a), None),
            RangeSpec::To(b) => (Some(1), Some(b)),
            RangeSpec::LastN(n) => if total > n { (Some(total - n + 1), Some(total)) } else { (Some(1), Some(total)) },
            RangeSpec::Plus(a, n) => (Some(a), Some(a.saturating_add(n))),
            RangeSpec::Ctx(a, n) => (Some(a.saturating_sub(n)), Some(a.saturating_add(n))),
            RangeSpec::LinesCtx(a, b, n) => (Some(a.saturating_sub(n)), Some(b.saturating_add(n))),
        };
        let s = s.unwrap_or(1).max(1);
        let e = e.unwrap_or(total).min(total);
        if s > e || e == 0 { continue; }
        out.push((s, e));
    }
    out.sort();
    let mut merged: Vec<(usize, usize)> = Vec::new();
    for (s, e) in out {
        if let Some(l) = merged.last_mut() {
            if s <= l.1.saturating_add(1) { if e > l.1 { l.1 = e; } continue; }
        }
        merged.push((s, e));
    }
    merged
}

fn digits(n: usize) -> usize { n.to_string().len() }

pub struct FileCtx<'a> {
    pub cfg: &'a Config,
    pub style: &'a [StyleComp],
    pub pr: &'a mut Printer<'a>,
    pub lang: Option<&'static Lang>,
}

pub struct Ctx;

#[allow(clippy::too_many_arguments)]
pub fn print_source(cfg: &Config, style: &[StyleComp], pr: &mut Printer, out: &mut dyn Write,
                    src: &Source, ranges: &[(usize, usize)], markers: Option<&Vec<char>>,
                    hl_state: &mut Vec<usize>, theme_name: &str, tc: bool,
                    is_first: bool, is_last: bool) {
    let header = style_has(style, StyleComp::HeaderFilename) || style_has(style, StyleComp::HeaderFilesize);
    let grid = style_has(style, StyleComp::Grid);
    let rule = style_has(style, StyleComp::Rule);
    let lang = src_lang(cfg, src);
    let langname = lang.map(|l| l.name).unwrap_or("plain text");

    if src.empty && !header { return; }
    let last = ranges.last().map(|r| r.1).unwrap_or(0);
    pr.numw = if style_has(style, StyleComp::Numbers) { std::cmp::max(4, digits(last.max(1))) } else { 0 };
    pr.has_changes = markers.map(|m| m.iter().any(|c| *c != ' ')).unwrap_or(false);

    if grid { pr.top_rule(out); }
    if header {
        if !is_first && !rule && !grid { writeln!(out).unwrap_or(()); }
        print_header(cfg, style, pr, out, src);
        if grid && !src.empty { pr.mid_rule(out); }
    }
    if src.empty { if grid { pr.bot_rule(out); } return; }

    let mut prev_blank = 0usize;
    let limit = cfg.squeeze_limit;
    for (si, (s, e)) in ranges.iter().enumerate() {
        if si > 0 && style_has(style, StyleComp::Snip) {
            let _ = writeln!(out, "{}", pr.snip_line());
        }
        for n in *s..=*e {
            let text = src.lines[n - 1].clone();
            if cfg.squeeze_blank && text.is_empty() {
                prev_blank += 1;
                if prev_blank > limit { continue; }
            } else { prev_blank = 0; }
            print_line(cfg, style, pr, out, src, n, &text, markers, hl_state, langname, theme_name, tc);
        }
    }
    if grid { pr.bot_rule(out); }
    if !is_last && rule && !grid { pr.horizontal(out); }
    let _ = lang;
}

pub fn src_lang(cfg: &Config, src: &Source) -> Option<&'static Lang> {
    if let Some(l) = &cfg.language { return crate::syntaxes::by_token(l); }
    // map-syntax
    for (g, s) in &cfg.map_syntax {
        if crate::glob::match_glob(g, &src.name) || crate::glob::match_glob(g, base_name(&src.name)) {
            if let Some(l) = crate::syntaxes::by_name(s) { return Some(l); }
            return None;
        }
    }
    if let Some(l) = crate::syntaxes::find_for_filename(&src.name) { return Some(l); }
    for suf in &cfg.ignored_suffixes {
        if let Some(stripped) = src.name.strip_suffix(suf.as_str()) {
            if let Some(l) = crate::syntaxes::find_for_filename(stripped) { return Some(l); }
        }
    }
    if let Some(f) = crate::syntaxes::find_for_filename(&base_name(&src.name)) { return Some(f); }
    // first line detection
    if let Some(first) = src.lines.first() {
        for l in crate::syntaxes::langs().iter() {
            for pat in &l.first_line {
                let re = crate::re::parse(pat);
                let chars: Vec<char> = first.chars().collect();
                if crate::re::find_from(&re, &chars, 0).is_some() { return Some(&**l); }
            }
        }
    }
    if let Some(f) = &cfg.fallback_syntax { return crate::syntaxes::by_token(f); }
    None
}

pub fn base_name(p: &str) -> &str { p.rsplit('/').next().unwrap_or(p) }

fn print_header(cfg: &Config, style: &[StyleComp], pr: &mut Printer, out: &mut dyn Write, src: &Source) {
    if style_has(style, StyleComp::HeaderFilename) {
        let extra = if src.empty { "   <EMPTY>" } else if src.binary && cfg.binary == BinaryMode::NoPrinting { "   <BINARY>" } else { "" };
        let full = format!("File: {}{}", src.name, extra);
        let cc = pr.content_col();
        let avail = if pr.term_width > cc { pr.term_width - cc } else { 0 };
        let wrapped = crate::wrap::char_wrap(&full, avail);
        for w in wrapped {
            let _ = writeln!(out, "{}{}", pr.header_prefix(), w);
        }
    }
    if style_has(style, StyleComp::HeaderFilesize) {
        let _ = writeln!(out, "{}Size: {}", pr.header_prefix(), human_size(src.size));
    }
}

pub fn human_size(n: usize) -> String {
    const UNITS: [&str; 7] = ["B", "KiB", "MiB", "GiB", "TiB", "PiB", "EiB"];
    let mut v = n as f64;
    let mut i = 0usize;
    while v >= 1024.0 && i < UNITS.len() - 1 { v /= 1024.0; i += 1; }
    if i == 0 { format!("{} B", n) } else { format!("{:.1} {}", v, UNITS[i]) }
}

#[allow(clippy::too_many_arguments)]
pub fn print_line(cfg: &Config, style: &[StyleComp], pr: &mut Printer, out: &mut dyn Write,
                  _src: &Source, n: usize, text: &str, markers: Option<&Vec<char>>,
                  hl_state: &mut Vec<usize>, langname: &str, theme_name: &str, tc: bool) {
    let marker = markers.and_then(|m| m.get(n - 1)).copied();
    let marker_char = match marker { Some(c @ ('+' | '-' | '~')) => c, _ => ' ' };
    let shown = if marker_char == ' ' { None } else { Some(marker_char) };
    let prefix = pr.line_prefix(Some(n), shown, false);
    let color = pr.color;
    let show_all = cfg.show_all;
    let tabs = cfg.tabs;
    let lang = crate::syntaxes::by_name(langname);
    let ats = crate::hl::atoms(text, lang, cfg, hl_state, tabs, show_all);
    let avail = pr.content_width();
    let word = cfg.wrap == WrapMode::Word;
    let parts = if pr.wrap && avail > 0 { crate::hl::wrap_atoms(&ats, avail, word) } else { vec![ats] };
    for (i, part) in parts.iter().enumerate() {
        let pf = if i == 0 { prefix.clone() } else { pr.header_prefix() };
        let body = crate::hl::render(part, color, langname, theme_name, tc, pr.italic);
        let _ = writeln!(out, "{}{}", pf, body);
    }
}

// stdin
pub fn render_stdin(cfg: &Config, style: &[StyleComp], pr: &mut Printer, out: &mut dyn Write, idx: usize) -> bool {
    let mut buf = Vec::new();
    let _ = std::io::Read::read_to_end(&mut std::io::stdin(), &mut buf);
    let name = cfg.file_name.clone().unwrap_or_else(|| "STDIN".to_string());
    let src = make_source(&buf, &name);
    if src.empty && cfg.quiet_empty { return false; }
    if src.empty && !style_has(style, StyleComp::HeaderFilename) && !style_has(style, StyleComp::HeaderFilesize) { return false; }
    let ranges = resolve_ranges(cfg, src.total);
    let mut state = vec![0usize];
    let theme_name = crate::theme::theme_name_for(cfg);
    print_source(cfg, style, pr, out, &src, &ranges, None, &mut state, &theme_name, crate::sys::truecolor(), idx == 0, true);
    true
}

pub fn render_file(cfg: &Config, style: &[StyleComp], pr: &mut Printer, out: &mut dyn Write,
                   path: &str, idx: usize, total: usize) -> Result<bool, String> {
    let src = read_file(path)?;
    if src.empty && cfg.quiet_empty { return Ok(false); }
    if src.empty && !style_has(style, StyleComp::HeaderFilename) && !style_has(style, StyleComp::HeaderFilesize) { return Ok(false); }
    let name = cfg.file_name.clone().unwrap_or_else(|| path.to_string());
    let mut src = src;
    src.name = name;
    let ranges = resolve_ranges(cfg, src.total);
    // binary handling
    let mut markers: Option<Vec<char>> = None;
    if style_has(style, StyleComp::Changes) || cfg.diff {
        markers = Some(crate::git::markers(cfg, &src));
    }
    if src.binary && cfg.binary == BinaryMode::NoPrinting && !cfg.show_all {
        let header = style_has(style, StyleComp::HeaderFilename) || style_has(style, StyleComp::HeaderFilesize);
        if !header {
            eprintln!("Binary content from file '{}' will not be printed to the terminal (but will be present if the output of 'bat' is piped). You can use 'bat -A' to show the binary file contents.", path);
            return Ok(false);
        }
    }
    let mut state = vec![0usize];
    let theme_name = crate::theme::theme_name_for(cfg);
    print_source(cfg, style, pr, out, &src, &ranges, markers.as_ref(), &mut state, &theme_name, crate::sys::truecolor(), idx == 0, idx + 1 == total);
    Ok(true)
}

pub fn atoms_of(text: &str, lang: Option<&Lang>, cfg: &Config, state: &mut Vec<usize>) -> Vec<Atom> {
    crate::hl::atoms(text, lang, cfg, state, cfg.tabs, cfg.show_all)
}
