use std::process::{Command, Stdio};

/// Content of the file as recorded in the git index (staged), if any.
pub fn index_content(path: &str) -> Option<String> {
    let dir = match std::path::Path::new(path).parent() {
        Some(d) if !d.as_os_str().is_empty() => d.to_path_buf(),
        _ => std::path::PathBuf::from("."),
    };
    let base = crate::render::base_name(path);
    let out = Command::new("git").arg("show").arg(format!(":./{}", base))
        .current_dir(&dir).stderr(Stdio::null()).output().ok()?;
    if !out.status.success() { return None; }
    Some(String::from_utf8_lossy(&out.stdout).to_string())
}

/// Myers diff between two line lists; returns hunks (old_start, old_len, new_start, new_len)
/// using 0-based indices.
pub fn diff_hunks(a: &[&str], b: &[&str]) -> Vec<(usize, usize, usize, usize)> {
    let n = a.len();
    let m = b.len();
    let max = n + m;
    if max > 20000 { return vec![]; }
    let mut v: Vec<i64> = vec![0; 2 * max + 1];
    let mut trace: Vec<Vec<i64>> = Vec::new();
    let offset = max as i64;
    let mut found = None;
    for d in 0..=max as i64 {
        let mut snapshot = v.clone();
        for k in (-d..=d).step_by(2) {
            let ki = (k + offset) as usize;
            let mut x: i64 = if k == -d || (k != d && v[ki - 1] < v[ki + 1]) { v[ki + 1] } else { v[ki - 1] + 1 };
            let mut y = x - k;
            while (x as usize) < n && (y as usize) < m && a[x as usize] == b[y as usize] { x += 1; y += 1; }
            v[ki] = x;
            if x as usize >= n && y as usize >= m { snapshot[ki] = x; trace.push(snapshot); found = Some(d); break; }
        }
        trace.push(snapshot);
        if let Some(dd) = found { let _ = dd; break; }
    }
    // backtrack
    let mut ops: Vec<(i64, i64)> = Vec::new(); // (del_count_at_old, ins_count_at_new)
    let mut x = n as i64;
    let mut y = m as i64;
    let mut d = found.unwrap_or(0);
    let mut idx = trace.len();
    while d > 0 {
        idx -= 1;
        let v = &trace[idx.saturating_sub(0)];
        let _ = v;
        let vv = &trace[idx];
        let k = x - y;
        let ki = (k + offset) as usize;
        let prev_k = if k == -d || (k != d && vv[ki - 1] < vv[ki + 1]) { k + 1 } else { k - 1 };
        let prev_ki = (prev_k + offset) as usize;
        let prev_x = vv[prev_ki];
        let prev_y = prev_x - prev_k;
        while x > prev_x && y > prev_y { x -= 1; y -= 1; }
        if prev_k == k + 1 {
            ops.push((0, 1)); // insertion at new y
            y -= 1;
        } else {
            ops.push((1, 0)); // deletion at old x
            x -= 1;
        }
        d -= 1;
    }
    ops.reverse();
    // convert ops to hunks
    let mut hunks: Vec<(usize, usize, usize, usize)> = Vec::new();
    let mut oi = 0usize;
    let mut ni = 0usize;
    let mut i = 0usize;
    while i < ops.len() {
        let (dl, il) = ops[i];
        let mut dcount = 0usize;
        let mut icount = 0usize;
        let start_o = oi;
        let start_n = ni;
        while i < ops.len() {
            let (d2, i2) = ops[i];
            if d2 == 1 && icount == 0 { dcount += 1; oi += 1; i += 1; }
            else if i2 == 1 && dcount == 0 { icount += 1; ni += 1; i += 1; }
            else { break; }
        }
        if dcount > 0 || icount > 0 {
            hunks.push((start_o, dcount, start_n, icount));
        }
        // common lines
        while i < ops.len() && ops[i] == (0, 0) { oi += 1; ni += 1; i += 1; }
    }
    hunks
}

/// Markers per line of the new content: ' ' unchanged, '~' modified, '+' added, '_' removed-above, '\u{203e}' removed-at-start
pub fn markers(index: &str, work: &str, nlines: usize) -> Vec<char> {
    let a: Vec<&str> = index.lines().collect();
    let b: Vec<&str> = work.lines().collect();
    let hunks = diff_hunks(&a, &b);
    let mut m: Vec<char> = vec![' '; nlines.max(1)];
    let mut any = false;
    for (os, ol, ns, nl) in hunks {
        if ol > 0 && nl > 0 {
            for i in 0..nl { let l = ns + i; if l < nlines { m[l] = '~'; any = true; } }
        } else if nl > 0 {
            for i in 0..nl { let l = ns + i; if l < nlines { m[l] = '+'; any = true; } }
        } else if ol > 0 {
            if ns == 0 {
                if nlines > 0 { m[0] = '\u{203e}'; any = true; }
            } else {
                let l = ns - 1;
                if l < nlines && m[l] == ' ' { m[l] = '_'; any = true; }
            }
        }
    }
    let _ = any;
    m
}
