        let mut snap = v.clone();
        for k in (-d..=d).step_by(2) {
            let idx = (k + offset) as usize;
            let xp = (k + 1 + offset) as usize;
            let xm = (k - 1 + offset) as usize;
            let mut x: isize = if k == -d || (k != d && v[xm] < v[xp]) { v[xp] } else { v[xm] + 1 };
            let mut y = x - k;
            while (x as usize) < n && (y as usize) < m && a[x as usize] == b[y as usize] { x += 1; y += 1; }
            snap[idx] = x;
            if x as usize >= n && y as usize >= m { d_final = d; done = true; break; }
        }
        trace.push(snap.clone());
        v = snap;
        if done { break; }
