        let prev_idx = (prev_k + offset) as usize;
        let prev_x = v_prev[prev_idx];
        let prev_y = prev_x - prev_k;
        while x > prev_x && y > prev_y { ops.push(0); x -= 1; y -= 1; }
        if x == prev_x { ops.push(2); y -= 1; } else { ops.push(1); x -= 1; }
        d -= 1;
    }
    while x > 0 && y > 0 { ops.push(0); x -= 1; y -= 1; }
    ops.reverse();
    // group into hunks
    let mut hunks: Vec<(usize, usize, usize, usize)> = Vec::new();
    let mut oi = 0usize;
    let mut ni = 0usize;
    let mut i = 0usize;
    let L = ops.len();
    while i < L {
        if ops[i] == 0 { oi += 1; ni += 1; i += 1; continue; }
        let start_o = oi;
        let start_n = ni;
        let mut dcount = 0usize;
