{"command": "cd /workspace; cat > src/main.rs <<'EOF'
mod args; mod parser; mod config; mod sys; mod wrap; mod out; mod theme; mod hl; mod pager;
mod info; mod re; mod syntax_list; mod syntaxes; mod impl_syntaxes; mod style_table;
mod theme_table; mod render; mod glob; mod git;

use config::*;
use std::io::Write;

pub fn main() {
    let defs = args::build_args();
    let argv: Vec<String> = std::env::args().skip(1).collect();

    if let Some(first) = argv.first() {
        if first == "cache" { info::cache_cmd(&argv[1..]); return; }
    }

    let mut all: Vec<String> = Vec::new();
    let mut no_config = false;
    for a in &argv { if a == "--no-config" { no_config = true; } }
    if !no_config {
        let p = crate::info::config_file_path();
        if let Ok(data) = std::fs::read_to_string(&p) {
            for line in data.lines() {
                let l = line.trim();
                if l.is_empty() || l.starts_with('#') { continue; }
                for w in crate::info::shell_words(l) { all.push(w); }
            }
        }
    }
    if let Ok(o) = std::env::var("BAT_OPTS") {
        for w in o.split_whitespace() { all.push(w.to_string()); }
    }
    all.extend(argv.iter().cloned());

    let parsed = match parser::parse(&all, &defs) {
        parser::PRes::Ok(p) => p,
        parser::PRes::Err(e) => { eprint!("{}", e.msg); std::process::exit(2); }
    };

    let mut cfg = config::def();
    let mut style_specs_raw: Vec<String> = Vec::new();
    for (di, v) in &parsed.items {
        let d = &defs[*di];
        if d.long == "style" { style_specs_raw.push(v.clone()); continue; }
        if let Err(e) = config::apply(&mut cfg, d, v) {
            eprint!("{}", e.0);
            std::process::exit(2);
        }
    }
    let mut style: Vec<StyleComp> = Vec::new();
    for spec in &style_specs_raw {
        match config::parse_style(spec) {
            Ok(s) => {
                let comps: Vec<&str> = spec.split(',').collect();
                let all_delta = !comps.is_empty() && comps.iter().all(|c| c.starts_with('+') || c.starts_with('-'));
                if all_delta {
                    for c in &s { if !style.contains(c) { style.push(*c); } }
                } else { style = s; }
            }
            Err(msg) => {
                let d = crate::args::find_long(&defs, "style").unwrap();
                eprint!("{}", crate::parser::invalid_value_msg(spec, d, &msg).msg);
                std::process::exit(2);
            }
        }
    }
    if style.is_empty() && style_specs_raw.is_empty() { style = DEFAULT_STYLE.to_vec(); }
    cfg.style = style.clone();
    cfg.files = parsed.positional.clone();

    if cfg.list_languages {
        if cfg.list_themes {
            eprint!("{}", crate::parser::conflict(crate::args::find_long(&defs, "list-languages").unwrap(), crate::args::find_long(&defs, "list-themes").unwrap()).msg);
            std::process::exit(2);
        }
        if cfg.config_file {
            eprint!("{}", crate::parser::conflict(crate::args::find_long(&defs, "list-languages").unwrap(), crate::args::find_long(&defs, "config-file").unwrap()).msg);
            std::process::exit(2);
        }
    }
    if cfg.list_themes && cfg.config_file {
        eprint!("{}", crate::parser::conflict(crate::args::find_long(&defs, "list-themes").unwrap(), crate::args::find_long(&defs, "config-file").unwrap()).msg);
        std::process::exit(2);
    }

    if cfg.version { println!("{}", args::VERSION); return; }
    if cfg.help { info::print_short_help(); return; }
    if cfg.long_help { info::print_help(); return; }
    if cfg.diagnostic { info::diagnostic(&cfg); return; }
    if let Some(sh) = &cfg.completion { info::completion(sh); return; }
    if cfg.list_languages { info::list_languages(); return; }
    if cfg.list_themes { info::list_themes(); return; }
    if cfg.config_file { println!("{}", crate::info::config_file_path()); return; }
    if cfg.config_dir { println!("{}", crate::info::config_dir()); return; }
    if cfg.cache_dir { println!("{}", crate::info::cache_dir()); return; }
    if cfg.generate_config_file { info::generate_config_file(); return; }
    if cfg.acknowledgements { info::acknowledgements(); return; }

    // warnings emitted before any output
    if crate::config::style_has(&style, StyleComp::Rule) && crate::config::style_has(&style, StyleComp::Grid) {
        eprintln!("Style 'rule' is a subset of style 'grid', 'rule' will not be visible.");
    }

    let paging = crate::pager::decide(&cfg);
    let use_pager = match paging { Tri::Always => true, _ => false };

    let out: Box<dyn Write> = if use_pager {
        match crate::pager::spawn(&crate::pager::command(&cfg)) {
            Some(w) => w,
            None => Box::new(std::io::stdout()),
        }
    } else {
        Box::new(std::io::stdout())
    };

    let _ = run(&cfg, &style, out);
}

fn run(cfg: &Config, style: &[StyleComp], mut out: Box<dyn Write>) -> Result<(), i32> {
    let color = match cfg.color {
        Tri::Always => true, Tri::Never => false, Tri::Auto => crate::sys::stdout_is_tty(),
    };
    let decor = match cfg.decorations {
        Tri::Always => true, Tri::Never => false, Tri::Auto => crate::sys::stdout_is_tty(),
    };
    let term_width = match cfg.terminal_width {
        Some(w) => w,
        None => crate::sys::tty_width().unwrap_or(80),
    };
    let wrap = match cfg.wrap {
        WrapMode::Never => false, WrapMode::Character => true, WrapMode::Word => true,
        WrapMode::Auto => decor,
    };
    let theme = crate::theme::resolve(cfg);
    let theme_name = crate::theme::theme_name_for(cfg);
    let style_eff: Vec<StyleComp> = if decor { style.to_vec() } else { Vec::new() };
    let mut pr = out::Printer::new(cfg, &style_eff, color, decor, &theme, term_width);
    pr.wrap = wrap;

    let mut any = false;
    if cfg.files.is_empty() {
        any = crate::render::render_stdin(cfg, &style_eff, &mut pr, &mut out, 0);
    } else {
        for (i, f) in cfg.files.iter().enumerate() {
            if f == "-" {
                any = crate::render::render_stdin(cfg, &style_eff, &mut pr, &mut out, i) || any;
            } else {
                match crate::render::render_file(cfg, &style_eff, &mut pr, &mut out, f, i, cfg.files.len()) {
                    Ok(true) => any = true,
                    Ok(false) => {}
                    Err(e) => {
                        let _ = out.flush();
                        eprint!("{}", e);
                        std::process::exit(1);
                    }
                }
            }
        }
    }
    let _ = any;
    let _ = out.flush();
    Ok(())
}
