use crate::hl::{Act, Lang, Rule};

// Python style ids (must match tools/specs.py order):
// 0 plain, 1 keyword, 2 func, 3 param, 4 num, 5 str, 6 esc, 7 comment,
// 8 builtin, 9 type, 10 class, 11 classbase, 12 op, 13 fprefix, 14 interp,
// 15 interp_id, 16 const, 17 punct
const P_PLAIN: u32 = 0;
const P_KW: u32 = 1;
const P_FUNC: u32 = 2;
const P_PARAM: u32 = 3;
const P_NUM: u32 = 4;
const P_STR: u32 = 5;
const P_ESC: u32 = 6;
const P_COM: u32 = 7;
const P_BUILTIN: u32 = 8;
const P_TYPE: u32 = 9;
const P_CLASS: u32 = 10;
const P_CLASSBASE: u32 = 11;
const P_OP: u32 = 12;
const P_PREFIX: u32 = 13;
const P_INTERP: u32 = 14;
const P_INTERP_ID: u32 = 15;
const P_CONST: u32 = 16;
const P_PUNCT: u32 = 17;

const PY_KW: &str = "(?:import|from|as|return|if|elif|else|for|while|in|not|and|or|is|lambda|try|except|finally|raise|with|yield|global|nonlocal|pass|break|continue|del|assert|async|await)\\b";
const PY_TYPES: &str = "(?:int|str|float|bool|list|dict|tuple|set|frozenset|bytes|bytearray|complex)";
const PY_BUILTINS: &str = "(?:print|len|range|open|isinstance|issubclass|type|super|property|staticmethod|classmethod|getattr|setattr|hasattr|delattr|input|format|repr|id|hash|iter|next|enumerate|zip|map|filter|min|max|sum|sorted|reversed|abs|all|any|callable|vars|dir|exec|eval|compile|ord|chr|hex|oct|bin|round|pow|divmod|__init__|__new__|__repr__|__str__|__len__|__call__|__getattr__|__setattr__|__enter__|__exit__|__iter__|__next__|__contains__|__getitem__|__setitem__|__delitem__|__eq__|__hash__|__bool__|__add__|__sub__)";

struct B { rules: Vec<Rule>, groups: Vec<Vec<usize>>, cur: usize }
impl B {
    fn new() -> B { B { rules: Vec::new(), groups: vec![Vec::new()], cur: 0 } }
    fn r(&mut self, pat: &'static str, kind: u32, act: Act) {
        let i = self.rules.len();
        self.rules.push(Rule { pat, kind, act, line_start: false });
        self.groups[self.cur].push(i);
    }
    fn s(&mut self, pat: &'static str, kind: u32, act: Act) {
        let i = self.rules.len();
        self.rules.push(Rule { pat, kind, act, line_start: true });
        self.groups[self.cur].push(i);
    }
    /// create a new (empty) state and switch to it
    fn st(&mut self) -> usize { self.groups.push(Vec::new()); self.cur = self.groups.len() - 1; self.cur }
    fn back(&mut self, i: usize) { self.cur = i; }
}

fn py() -> Lang {
    let mut b = B::new();
    let main = 0usize;
    b.s("@", P_OP, Act::None);
    b.r("#[^\\n]*", P_COM, Act::None);
    b.r("[rRbBuUfF]+(?=[\"'])", P_PREFIX, Act::None);
    let s3 = b.st(); b.r("\"\"\"", P_STR, Act::Push(s3));
    b.back(main);
    let s4 = b.st(); b.r("'''", P_STR, Act::Push(s4));
    b.back(main);
    let s1 = b.st(); b.r("\"", P_STR, Act::Push(s1));
    b.back(main);
    let s2 = b.st(); b.r("'", P_STR, Act::Push(s2));
    b.back(main);
    b.r(PY_KW, P_KW, Act::None);
    let s5 = b.st(); b.r("\\bdef\\b", P_KW, Act::Push(s5));
    b.back(main);
    let s7 = b.st(); b.r("\\bclass\\b", P_KW, Act::Push(s7));
    b.back(main);
    b.r(PY_TYPES, P_TYPE, Act::None);
    b.r(PY_BUILTINS, P_BUILTIN, Act::None);
    b.r("\\b(True|False|None)\\b", P_CONST, Act::None);
    b.r("\\b0[xX][0-9a-fA-F_]+", P_NUM, Act::None);
    b.r("\\b0[bB][01_]+", P_NUM, Act::None);
    b.r("\\b0[oO][0-7_]+", P_NUM, Act::None);
    b.r("\\b[0-9][0-9_]*(\\.[0-9_]+)?([eE][-+]?[0-9]+)?", P_NUM, Act::None);
    b.r("[-+*/%=<>!&|^~]+", P_OP, Act::None);
    b.r("[()\\[\\]{},:.;]", P_PUNCT, Act::None);
    b.r("\\b[a-zA-Z_][a-zA-Z0-9_]*\\b", P_PLAIN, Act::None);
    // string states
    b.back(s1);
    b.r("\\\\.", P_ESC, Act::None);
    b.r("\"", P_STR, Act::Pop);
    b.r("[^\"\\\\]+", P_STR, Act::None);
    b.r(".", P_STR, Act::None);
    b.back(s2);
    b.r("\\\\.", P_ESC, Act::None);
    b.r("'", P_STR, Act::Pop);
    b.r("[^'\\\\]+", P_STR, Act::None);
    b.r(".", P_STR, Act::None);
    b.back(s3);
    b.r("\\\\.", P_ESC, Act::None);
    b.r("\"\"\"", P_STR, Act::Pop);
    b.r("[^\"\\\\]+", P_STR, Act::None);
    b.r("\"{1,2}", P_STR, Act::None);
    b.r(".", P_STR, Act::None);
    b.back(s4);
    b.r("\\\\.", P_ESC, Act::None);
    b.r("'''", P_STR, Act::Pop);
    b.r("[^'\\\\]+", P_STR, Act::None);
    b.r(".", P_STR, Act::None);
    b.back(s5);
    b.r("\\s+", P_PLAIN, Act::None);
    b.r("__[a-zA-Z0-9_]+__", P_BUILTIN, Act::Pop);
    b.r("[a-zA-Z_][a-zA-Z0-9_]*", P_FUNC, Act::Pop);
    b.back(s7);
    b.r("\\s+", P_PLAIN, Act::None);
    b.r("[a-zA-Z_][a-zA-Z0-9_]*", P_CLASS, Act::Pop);
    Lang::new("python", vec!["py","py3","pyw","pyi","pyx","pxd","pxi","rpy","cpy"], b.rules, b.groups,
              vec!["^#!\\s*.*python", "^#!\\s*.*python\\d"])
}

pub fn build() -> Vec<Box<Lang>> { vec![Box::new(py())] }
