    b.r("\"{1,2}", P_STR, Act::None);
    b.r(".", P_STR, Act::None);
    b.back(s3c);
    b.r("\\\\.", P_ESC, Act::None);
    b.r("\"\"\"", P_STR, Act::Pop);
    b.r("[^\"\\\\]+", P_STR, Act::None);
    b.r(".", P_STR, Act::None);
    b.back(s4);
    b.r("\\\\.", P_ESC, Act::None);
    b.r("'''", P_STR, Act::Pop);
    b.r("[^'\\\\]+", P_STR, Act::None);
    b.r(".", P_STR, Act::None);
    b.back(s4c);
    b.r("\\\\.", P_ESC, Act::None);
    b.r("'''", P_STR, Act::Pop);
    b.r("[^'\\\\]+", P_STR, Act::None);
    b.r(".", P_STR, Act::None);
    // after def
    b.back(s5);
    b.r("\\s+", P_PLAIN, Act::None);
    b.r("__[a-zA-Z0-9_]+__", P_BUILTIN, Act::None);
    b.r("[a-zA-Z_][a-zA-Z0-9_]*", P_FUNC, Act::None);
    b.r(PY_TYPES, P_TYPE, Act::None);
    b.r(PY_BUILTINS, P_BUILTIN, Act::None);
    b.r("\\(", P_PUNCT, Act::Push(0)); // param list, fixed below
    b.r("\\)", P_PUNCT, Act::Pop);
    b.r(",", P_PUNCT, Act::None);
    b.r(":", P_PUNCT, Act::Pop);
    b.r("->", P_PLAIN, Act::None);
    b.r("\\*+", P_OP, Act::None);
    b.r("=", P_OP, Act::None);
    b.r(".", P_PLAIN, Act::None);
    // param list (state index patched after creation)
    let s6 = b.st();
    b.back(s6);
    b.r("\\)", P_PUNCT, Act::Pop);
    b.r("\\bself\\b", P_PARAM, Act::None);
    b.r("[a-zA-Z_][a-zA-Z0-9_]*", P_PARAM, Act::None);
    b.r(",", P_PUNCT, Act::None);
    b.r(":", P_PUNCT, Act::None);
    b.r("\\*+", P_OP, Act::None);
    b.r("=", P_OP, Act::None);
    b.r("\\s+", P_PLAIN, Act::None);
    b.r(".", P_PLAIN, Act::None);
    // after class name
    b.back(s7);
    b.r("\\s+", P_PLAIN, Act::None);
    b.r("[a-zA-Z_][a-zA-Z0-9_]*", P_CLASS, Act::None);
    b.r("\\(", P_PUNCT, Act::Push(0));
    b.r(":", P_PUNCT, Act::Pop);
    b.r(".", P_PLAIN, Act::None);
    // class base
    let s9 = b.st();
    b.back(s9);
    b.r("\\)", P_PUNCT, Act::Pop);
    b.r("[a-zA-Z_][a-zA-Z0-9_]*(?=\\s*=)", P_PARAM, Act::None);
    b.r("[a-zA-Z_][a-zA-Z0-9_]*", P_CLASSBASE, Act::None);
    b.r(",", P_PUNCT, Act::None);
    b.r("\\s+", P_PLAIN, Act::None);
    b.r(".", P_PLAIN, Act::None);
    // patch Push targets
    for r in b.rules.iter_mut() {
        if r.act == Act::Push(0) { r.act = Act::Push(if b.cur == s9 { s6 } else { s6 }); }
    }
    // fix: rules in s5 pushing '(' -> param list; rules in s7 pushing '(' -> class base
    patch_pushes(&mut b, s5, s6, s7, s9);
    Lang::new("python", vec!["py","py3","pyw","pyi","pyx","pxd","pxi","rpy","cpy"], b.rules, b.groups,
              vec!["^#!\\s*.*python", "^#!\\s*.*python\\d"])
}

fn patch_pushes(b: &mut B, s5: usize, s6: usize, s7: usize, s9: usize) {
    // rules in state s5 whose pattern is "(" push s6; in s7 push s9
    let s5_rules: Vec<usize> = b.groups[s5].clone();
    let s7_rules: Vec<usize> = b.groups[s7].clone();
    for i in s5_rules { if b.rules[i].pat == "\\(" { b.rules[i].act = Act::Push(s6); } }
    for i in s7_rules { if b.rules[i].pat == "\\(" { b.rules[i].act = Act::Push(s9); } }
}

pub fn build() -> Vec<Box<Lang>> { vec![Box::new(py())] }
