use crate::hl::{Act, Lang, Rule};
use crate::style_ids::style_ids::python::{PLAIN as P_PLAIN, KEYWORD as P_KW, FUNC as P_FUNC,
    PARAM as P_PARAM, NUM as P_NUM, STR as P_STR, ESC as P_ESC, COMMENT as P_COM,
    COMMENT_PUNCT as P_COMPUNCT, BUILTIN as P_BUILTIN, TYPE as P_TYPE, CLASS as P_CLASS,
    CLASSBASE as P_CLASSBASE, OP as P_OP, FPREFIX as P_PREFIX, INTERP as P_INTERP,
    INTERP_ID as P_INTERP_ID, CONST as P_CONST, PUNCT as P_PUNCT};

const PY_KW: &str = "(?:import|from|as|return|if|elif|else|for|while|in|not|and|or|is|lambda|try|except|finally|raise|with|yield|global|nonlocal|pass|break|continue|del|assert|async|await)\\b";
const PY_TYPES: &str = "(?:int|str|float|bool|list|dict|tuple|set|frozenset|bytes|bytearray|complex)";
const PY_BUILTINS: &str = "(?:print|len|range|open|isinstance|issubclass|type|super|property|staticmethod|classmethod|getattr|setattr|hasattr|delattr|input|format|repr|id|hash|iter|next|enumerate|zip|map|filter|min|max|sum|sorted|reversed|abs|all|any|callable|vars|dir|exec|eval|compile|ord|chr|hex|oct|bin|round|pow|divmod|__init__|__new__|__repr__|__str__|__len__|__call__|__getattr__|__setattr__|__enter__|__exit__|__iter__|__next__|__contains__|__getitem__|__setitem__|__delitem__|__eq__|__hash__|__bool__|__add__|__sub__)";

struct B { rules: Vec<Rule>, groups: Vec<Vec<usize>>, cur: usize }
impl B {
    fn new() -> B { B { rules: Vec::new(), groups: vec![Vec::new()], cur: 0 } }
    fn r(&mut self, pat: &'static str, kind: u32, act: Act) {
        let i = self.rules.len();
        self.rules.push(Rule { pat, kind, act, line_start: false });
        self.groups[self.cur].push(i);
    }
    fn s(&mut self, pat: &'static str, kind: u32, act: Act) {
        let i = self.rules.len();
        self.rules.push(Rule { pat, kind, act, line_start: true });
        self.groups[self.cur].push(i);
    }
    fn st(&mut self) -> usize { self.groups.push(Vec::new()); self.groups.len() - 1 }
    fn back(&mut self, i: usize) { self.cur = i; }
}

/// numeric / operator / punctuation rules shared by several states
fn value_rules(b: &mut B, here: usize) {
    let sh = b.st(); b.back(here); b.r("\\b0[xX]", P_NUM, Act::Push(sh));
    b.back(sh); b.r("[0-9a-fA-F_]+", P_NUM, Act::Pop); b.back(here);
    let sb2 = b.st(); b.back(here); b.r("\\b0[bB]", P_NUM, Act::Push(sb2));
    b.back(sb2); b.r("[01_]+", P_NUM, Act::Pop); b.back(here);
    let so = b.st(); b.back(here); b.r("\\b0[oO]", P_NUM, Act::Push(so));
    b.back(so); b.r("[0-7_]+", P_NUM, Act::Pop); b.back(here);
    let sd = b.st(); b.back(here); b.r("\\d[\\d_]*(?=\\.)", P_NUM, Act::Push(sd));
    b.back(sd); b.r("\\.", P_NUM, Act::Pop); b.back(here);
    b.r("\\d[\\d_]*([eE][-+]?[0-9]+)?(?![\\d.])", P_NUM, Act::None);
    b.r("[-+*/%=<>!&|^~]+", P_OP, Act::None);
    b.r("[()\\[\\]{},:.;]", P_PUNCT, Act::None);
    b.r("\\\\", P_PLAIN, Act::None);
}

fn py() -> Lang {
    let mut b = B::new();
    let main = b.cur;
    b.s("@", P_PLAIN, Act::None);
    let scom = b.st(); b.back(main); b.r("#", P_COMPUNCT, Act::Push(scom));
    b.back(scom); b.r("[^\\n]*", P_COM, Act::Pop); b.back(main);
    b.r("[rRbBuUfF]+(?=[\"'])", P_PREFIX, Act::None);
    let s3c = b.st(); b.back(main); b.s("\"\"\"", P_COM, Act::Push(s3c));
    let s3 = b.st(); b.back(main); b.r("\"\"\"", P_STR, Act::Push(s3));
    let s4c = b.st(); b.back(main); b.s("'''", P_COM, Act::Push(s4c));
    let s4 = b.st(); b.back(main); b.r("'''", P_STR, Act::Push(s4));
    let s1 = b.st(); b.back(main); b.r("\"", P_STR, Act::Push(s1));
    let s2 = b.st(); b.back(main); b.r("'", P_STR, Act::Push(s2));
    b.r(PY_KW, P_KW, Act::None);
    let s5 = b.st(); b.back(main); b.r("\\bdef\\b", P_KW, Act::Push(s5));
    let s7 = b.st(); b.back(main); b.r("\\bclass\\b", P_KW, Act::Push(s7));
    b.r(PY_TYPES, P_TYPE, Act::None);
    b.r(PY_BUILTINS, P_BUILTIN, Act::None);
    b.r("\\b(True|False|None)\\b", P_CONST, Act::None);
    value_rules(&mut b, main);
    b.r("\\b[a-zA-Z_][a-zA-Z0-9_]*\\b", P_PLAIN, Act::None);
    // strings
    b.back(s1); b.r("\\\\.", P_ESC, Act::None); b.r("\"", P_STR, Act::Pop);
    b.r("[^\"\\\\]+", P_STR, Act::None); b.r(".", P_STR, Act::None);
    b.back(s2); b.r("\\\\.", P_ESC, Act::None); b.r("'", P_STR, Act::Pop);
    b.r("[^'\\\\]+", P_STR, Act::None); b.r(".", P_STR, Act::None);
    b.back(s3); b.r("\\\\.", P_ESC, Act::None); b.r("\"\"\"", P_STR, Act::Pop);
    b.r("[^\"\\\\]+", P_STR, Act::None); b.r("\"{1,2}", P_STR, Act::None); b.r(".", P_STR, Act::None);
    b.back(s3c); b.r("\\\\.", P_ESC, Act::None); b.r("\"\"\"", P_COM, Act::Pop);
    b.r("[^\"\\\\]+", P_COM, Act::None); b.r(".", P_COM, Act::None);
    b.back(s4); b.r("\\\\.", P_ESC, Act::None); b.r("'''", P_STR, Act::Pop);
    b.r("[^'\\\\]+", P_STR, Act::None); b.r(".", P_STR, Act::None);
    b.back(s4c); b.r("\\\\.", P_ESC, Act::None); b.r("'''", P_COM, Act::Pop);
    b.r("[^'\\\\]+", P_COM, Act::None); b.r(".", P_COM, Act::None);
    // after def
    b.back(s5);
    b.r("\\s+", P_PLAIN, Act::None);
    b.r("__[a-zA-Z0-9_]+__", P_BUILTIN, Act::None);
    b.r("[a-zA-Z_][a-zA-Z0-9_]*", P_FUNC, Act::None);
    b.r(PY_TYPES, P_TYPE, Act::None);
    b.r(PY_BUILTINS, P_BUILTIN, Act::None);
    b.r("\\(", P_PUNCT, Act::Push(0));
    b.r("\\)", P_PUNCT, Act::Pop);
    b.r(",", P_PUNCT, Act::None);
    b.r(":", P_PUNCT, Act::Pop);
    b.r("->", P_PLAIN, Act::None);
    b.r("\\*+", P_OP, Act::None);
    b.r("=", P_OP, Act::None);
    b.r(".", P_PLAIN, Act::None);
    // param list
    let s6 = b.st(); b.back(s6);
    b.r("\\)", P_PUNCT, Act::Pop);
    b.r(PY_TYPES, P_TYPE, Act::None);
    b.r(PY_BUILTINS, P_BUILTIN, Act::None);
    b.r("\\b(True|False|None)\\b", P_CONST, Act::None);
    value_rules(&mut b, s6);
    b.r("\\bself\\b", P_PARAM, Act::None);
    b.r("[a-zA-Z_][a-zA-Z0-9_]*", P_PARAM, Act::None);
    b.r("\\s+", P_PLAIN, Act::None);
    b.r(".", P_PLAIN, Act::None);
    b.back(s5);
    for i in b.groups[s5].clone() { if b.rules[i].pat == "\\(" { b.rules[i].act = Act::Push(s6); } }
    // after class
    b.back(s7);
    b.r("\\s+", P_PLAIN, Act::None);
    b.r("[a-zA-Z_][a-zA-Z0-9_]*", P_CLASS, Act::None);
    b.r("\\(", P_PUNCT, Act::Push(0));
    b.r(":", P_PUNCT, Act::Pop);
    b.r(".", P_PLAIN, Act::None);
    // class base
    let s9 = b.st(); b.back(s9);
    b.r("\\)", P_PUNCT, Act::Pop);
    b.r("=", P_OP, Act::None);
    b.r("[a-zA-Z_][a-zA-Z0-9_]*(?=\\s*=)", P_PARAM, Act::None);
    b.r("[a-zA-Z_][a-zA-Z0-9_]*", P_CLASSBASE, Act::None);
    b.r(",", P_PUNCT, Act::None);
    b.r("\\s+", P_PLAIN, Act::None);
    b.r(".", P_PLAIN, Act::None);
    b.back(s7);
    for i in b.groups[s7].clone() { if b.rules[i].pat == "\\(" { b.rules[i].act = Act::Push(s9); } }
    Lang::new("python", vec!["py","py3","pyw","pyi","pyx","pxd","pxi","rpy","cpy"], b.rules, b.groups,
              vec!["^#!\\s*.*python", "^#!\\s*.*python\\d"])
}

