{"command": "cd /workspace; python3 - <<'PY'
import subprocess,re
# build probe with distinct control chars separated by markers
chars = {'tab':'\t','cr':'\r','vt':'\x0b','ff':'\x0c','esc':'\x1b','bel':'\x07','bs':'\x08','del':'\x7f','nul':'\x00','soh':'\x01','stx':'\x02','sp':' '}
lines=[]
for k,v in chars.items():
    lines.append('Z%sZ%sZ%sZ'%(k,v,k))
open('/tmp/np_probe.txt','wb').write('\n'.join(lines).encode()+b'\n')
def segs(args,tc=False):
    e=dict(os.environ)
    if tc: e['COLORTERM']='truecolor'
    p=subprocess.run(args,capture_output=True,env=e,cwd='/workspace')
    out=p.stdout.decode('utf8','replace')
    parts=re.split(r'(\x1b\[[0-9;]*m)',out)
    r=[];cur=''
    for x in parts:
        if x.startswith('\x1b['): cur=x[2:-1]
        elif x: r.append((cur,x))
    return r
themes=[l.strip() for l in open('assets/themes.txt') if l.strip()]
res={}
ph={ 'tab':'\u251c','cr':'\u240d','vt':'\u240b','ff':'\u240c','esc':'\u241b','bel':'\u2407','bs':'\u2408','del':'\u2421','nul':'\u2400','soh':'\u2401','stx':'\u2402','sp':'\u00b7','nl':'\u240a'}
for t in themes:
    d={}
    for mode,tc in (('256',False),('tc',True)):
        rr=segs(['./executable','--color=always','--decorations=never','-A','--theme='+t,'/tmp/np_probe.txt'],tc)
        for k,c in ph.items():
            code=None
            for s,x in rr:
                if c in x: code=s; break
            d[(k,mode)]=code or '!!'
        # plain text color: find run 'ZtabZ'
        for s,x in rr:
            if x.startswith('ZtabZ'): d[('plain',mode)]=s; break
        else: d[('plain',mode)]='!!'
        # unicode escape color
        for s,x in rr:
            if '\\u' in x: d[('uni',mode)]=s; break
        else: d[('uni',mode)]='!!'
    res[t]=d
bad=set()
for t,d in res.items():
    for k,v in d.items():
        if v=='!!': bad.add(k[0])
print('unknowns:',bad)
out=['// Generated: non-printable placeholder colours per theme.',
     "pub struct NpRow { pub theme: &'static str, pub codes: &'static [(u32, &'static str, &'static str)] }",
     'pub static NP_ROWS: &[NpRow] = &[']
order=['plain','tab','nl','cr','vt','ff','esc','bel','bs','del','nul','soh','stx','sp','uni']
for t in themes:
    d=res[t]
    ents=[]
    for i,k in enumerate(order):
        ents.append('(%d, "%s", "%s")' % (i, d[(k,'256')] or '', d[(k,'tc')] or ''))
    out.append('    NpRow { theme: "%s", codes: &[%s] },' % (t, ', '.join(ents)))
out.append('];')
open('src/np_table.rs','w').write('\n'.join(out)+'\n')
print('done')
for k in order: print(k, res['Monokai Extended'][(k,'256')], res['ansi'][(k,'256')])
PY"}

