#[derive(Clone)]
pub struct Atom { pub code: String, pub text: String, pub w: usize }

pub const NP_PLAIN: u32 = 0;
pub const NP_TAB: u32 = 1;
pub const NP_NL: u32 = 2;
pub const NP_CR: u32 = 3;
pub const NP_CTRL: u32 = 4;
pub const NP_ESC: u32 = 5;
pub const NP_SP: u32 = 6;
pub const NP_UNI: u32 = 7;

pub fn np_code(theme: &str, tc: bool, id: u32) -> String {
    for r in crate::np_table::NP_ROWS.iter() {
        if r.theme == theme {
            for (i, c256, ctc) in r.codes {
                if *i == id { return if tc { ctc.to_string() } else { c256.to_string() }; }
            }
            break;
        }
    }
    String::new()
}

pub struct NpCodes { pub c: [String; 8] }
pub fn np_codes(theme: &str, tc: bool) -> NpCodes {
    NpCodes { c: [NP_PLAIN, NP_TAB, NP_NL, NP_CR, NP_CTRL, NP_ESC, NP_SP, NP_UNI]
        .map(|i| np_code(theme, tc, i)) }
}''')
# rewrite atoms / push_style_text / render to use codes
i=s.find('/// Build atoms from a line, applying --show-all transformations and tab expansion.')
j=s.find('/// Wrap atoms into lines of at most `width` display columns.')
new = '''/// Build atoms from a line, applying --show-all transformations and tab expansion.
pub fn atoms(line: &str, lang: Option<&Lang>, cfg: &Config, state: &mut Vec<usize>, tabs: usize,
             show_all: bool, langname: &str, theme: &str, tc: bool) -> Vec<Atom> {
    let np = np_codes(theme, tc);
    let plain_code = lookup(langname, theme, 0, tc);
    let tokens = match lang {
        Some(l) => tokenize(l, line, state),
        None => vec![(0u32, line.to_string())],
    };
    let mut out: Vec<Atom> = Vec::new();
    let mut col = 0usize;
    for (style, text) in tokens {
        let code = if style == 0 { plain_code.clone() } else { lookup(langname, theme, style, tc) };
        push_style_text(&mut out, &code, &text, &np, &mut col, tabs, show_all);
    }
    if show_all { out.push(Atom { code: np.c[NP_NL as usize].clone(), text: "\\u{240a}".to_string(), w: 1 }); }
    out
}

fn push_style_text(out: &mut Vec<Atom>, code: &str, text: &str, np: &NpCodes, col: &mut usize,
                   tabs: usize, show_all: bool) {
    if show_all {
        for ch in text.chars() {
            let cp = ch as u32;
            let (ncode, rep, w) = match ch {
                '\\t' => { let t = if tabs == 0 { 4 } else { tabs };
                          let adv = t - (*col % t);
                          (np.c[NP_TAB as usize].clone(), tab_placeholder(adv), adv) }
                ' ' => (np.c[NP_SP as usize].clone(), space_placeholder(), 1),
                '\\r' => (np.c[NP_CR as usize].clone(), control_placeholder(cp).unwrap().0.to_string(), 1),
                '\\n' => (np.c[NP_NL as usize].clone(), "\\u{240a}".to_string(), 1),
                _ => {
                    if let Some((ph, w)) = control_placeholder(cp) {
                        let id = match cp { 0x00 | 0x07 | 0x08 | 0x1b => NP_ESC, _ => NP_CTRL };
                        (np.c[id as usize].clone(), ph.to_string(), w)
                    } else if cp > 0x7e {
                        (np.c[NP_UNI as usize].clone(), unicode_escape(cp), 1)
                    } else {
                        (code.to_string(), ch.to_string(), 1)
                    }
                }
            };
            out.push(Atom { code: ncode, text: rep, w });
            *col += w;
        }
        return;
    }
    if tabs == 0 {
        let w = crate::wrap::display_width(text);
        out.push(Atom { code: code.to_string(), text: text.to_string(), w });
        *col += w;
        return;
    }
    let mut cur = String::new();
    let mut curw = 0usize;
    for ch in text.chars() {
        if ch == '\\t' {
            if !cur.is_empty() { out.push(Atom { code: code.to_string(), text: std::mem::take(&mut cur), w: curw }); *col += curw; curw = 0; }
            let adv = tabs - (*col % tabs);
            let sp: String = std::iter::repeat(' ').take(adv).collect();
            out.push(Atom { code: code.to_string(), text: sp, w: adv });
            *col += adv;
        } else {
            cur.push(ch);
            curw += crate::wrap::char_width(ch);
        }
    }
    if !cur.is_empty() { out.push(Atom { code: code.to_string(), text: cur, w: curw }); *col += curw; }
}

'''
s = s[:i] + new + s[j:]
