new = '''/// Word wrapping similar to textwrap::fill with break_words enabled.
pub fn word_wrap(atoms: &[Atom], width: usize) -> Vec<Vec<Atom>> {
    if width == 0 { return vec![atoms.to_vec()]; }
    // split into pieces
    let mut pieces: Vec<(String, String, usize, bool)> = Vec::new(); // (code, text, w, is_space)
    for a in atoms {
        let mut word = String::new();
        let mut ww = 0usize;
        let mut sp = String::new();
        let mut spw = 0usize;
        for ch in a.text.chars() {
            if ch == ' ' {
                if !word.is_empty() { pieces.push((a.code.clone(), std::mem::take(&mut word), ww, false)); ww = 0; }
                sp.push(ch); spw += 1;
            } else {
                if !sp.is_empty() { pieces.push((a.code.clone(), std::mem::take(&mut sp), spw, true)); spw = 0; }
                word.push(ch); ww += crate::wrap::char_width(ch);
            }
        }
        if !word.is_empty() { pieces.push((a.code.clone(), word, ww, false)); }
        if !sp.is_empty() { pieces.push((a.code.clone(), sp, spw, true)); }
    }
    let mut lines: Vec<Vec<Atom>> = Vec::new();
    let mut cur: Vec<Atom> = Vec::new();
    let mut curw = 0usize;
    let mut pend: Option<Atom> = None;
    for (code, text, w, is_space) in pieces {
        if is_space {
            match &mut pend {
                Some(p) => { p.text.push_str(&text); p.w += w; }
                None => { pend = Some(Atom { code: code.clone(), text, w, ph: false, nm: false }); }
            }
            continue;
        }
        let sepw = match &pend { Some(p) => if cur.is_empty() { 0 } else { p.w }, None => 0 };
        if curw + sepw + w <= width {
            if let Some(p) = pend.take() { if !cur.is_empty() { curw += p.w; cur.push(p); } }
            cur.push(Atom { code, text, w, ph: false, nm: false });
            curw += w;
        } else {
            if !cur.is_empty() { lines.push(std::mem::take(&mut cur)); curw = 0; }
            pend = None;
            if w > width {
                let mut buf = String::new();
                let mut bw = 0usize;
                for c in text.chars() {
                    let cw = crate::wrap::char_width(c);
                    if bw + cw > width && bw > 0 {
                        cur.push(Atom { code: code.clone(), text: std::mem::take(&mut buf), w: bw, ph: false, nm: false });
                        lines.push(std::mem::take(&mut cur));
                        bw = 0;
                    }
                    buf.push(c); bw += cw;
                }
                if !buf.is_empty() { cur.push(Atom { code, text: buf, w: bw, ph: false, nm: false }); curw = bw; }
            } else {
                cur.push(Atom { code, text, w, ph: false, nm: false });
                curw = w;
            }
        }
    }
    if !cur.is_empty() || lines.is_empty() { lines.push(cur); }
    lines
}

